using UnityEngine;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;

public class UdpReceiver : MonoBehaviour
{
    public int listenPort = 5005;
    public BallController ballController; // assign in inspector
    UdpClient udpClient;
    Thread listenThread;
    bool running;

    void Start()
    {
        if (ballController == null)
        {
            return;
        }

        // Use the BallController's queue
        if (ballController.hitQueue == null)
            ballController.hitQueue = new ConcurrentQueue<HitData>();

        StartListener();
    }

    void StartListener()
    {
        udpClient = new UdpClient(listenPort);
        running = true;
        listenThread = new Thread(new ThreadStart(ListenLoop));
        listenThread.IsBackground = true;
        listenThread.Start();
        Debug.Log($"UDP listener started on port {listenPort}");
    }

    void ListenLoop()
    {
        IPEndPoint remoteEP = new IPEndPoint(IPAddress.Any, listenPort);
        while (running)
        {
            try
            {
                byte[] data = udpClient.Receive(ref remoteEP); // blocking
                string msg = Encoding.UTF8.GetString(data);
                // Try parse JSON to HitData
                HitData hit = ParseHitJson(msg);
                if (hit != null)
                {
                    // If timestamp is not provided, you could set it here to local time:
                    if (hit.timestamp == 0) hit.timestamp = Time.time;
                    ballController.hitQueue.Enqueue(hit);
                }
            }
            catch (SocketException ex)
            {
                if (running) Debug.LogWarning("UDP recv error: " + ex.Message);
            }
            catch (System.Exception ex)
            {
                Debug.LogError("UDP listener error: " + ex);
            }
        }
    }

    HitData ParseHitJson(string json)
    {
        try
        {
            // Unity's JsonUtility requires a wrapper for arrays; since HitData has float[] fields,
            // one reliable approach is to use Simple JSON like MiniJSON or a lightweight JSON library.
            // For clarity here, we'll use JsonUtility with a small tweak: ensure the middleware sends arrays as lists.
            return JsonUtility.FromJson<HitData>(json);
        }
        catch
        {
            Debug.LogWarning("Failed to parse hit JSON: " + json);
            return null;
        }
    }

    void OnDestroy()
    {
        running = false;
        if (udpClient != null) udpClient.Close();
        if (listenThread != null && listenThread.IsAlive) listenThread.Abort();
    }
}

