1	using UnityEngine;
2	using System.Collections.Concurrent;
3	
4	[RequireComponent(typeof(Rigidbody))]
5	public class BallController : MonoBehaviour
6	{
7	    [Header("Speed / spin mapping")]
8	    public float maxSpeed = 20f; // m/s when speed_norm == 1
9	    public bool overwriteVelocity = true;      // if true sets rb.velocity directly; otherwise AddForce impulse
10	
11	    [Header("Magnus (curve)")]
12	    [Tooltip("Magnus force scale. Increase to get stronger curve. Typical starting value: 0.2 - 2.0")]
13	    public float magnusFactor = 0.1f; // Reduced from 0.3f - less extreme curves
14	
15	    [Tooltip("Apply Magnus as Force (continuous) or Impulse (single big push)")]
16	    public ForceMode magnusForceMode = ForceMode.Force;
17	
18	    [Header("Physics Decay")]
19	    [Tooltip("Air resistance coefficient - reduces velocity over time when airborne")]
20	    public float airDrag = 0.05f; // Simple percentage per second (5% per second)
21	
22	    [Tooltip("Ground friction coefficient - reduces velocity when ball is on ground")]
23	    public float groundFriction = 0.2f; // Simple percentage per second (20% per second)
24	
25	    [Tooltip("Linear drag coefficient - helps ball stop at low speeds")]
26	    public float linearDrag = 0.02f; // Not used in simplified system
27	
28	    [Tooltip("Spin decay rate - how quickly spin reduces over time")]
29	    public float spinDecay = 0.8f; // per second - reduced from 0.8 for longer lasting spin
30	
31	    [Tooltip("Ground contact detection - how close to ground counts as 'on ground'")]
32	    public float groundCheckDistance = 0.1f;
33	
34	    [Tooltip("Minimum velocity before ball stops completely")]
35	    public float minVelocityThreshold = 0.01f; // When below this, ball velocity is set to zero
36	
37	    [Header("Bounce Physics")]
38	    [Tooltip("How much velocity is retained after bouncing (0 = no bounce, 1 = perfect bounce)")]
39	    public float bounceCoefficient = 0.3f; // Reduced from 0.6f for less bouncy net interaction
40	
41	    [Tooltip("Minimum vertical velocity needed to trigger a bounce")]
42	    public float minBounceVelocity = 2f;
43	
44	    [Tooltip("How much horizontal velocity is retained during bounce (surface friction)")]
45	    public float horizontalDamping = 0.4f; // Reduced from 0.8f for more friction with net
46	
47	    [Tooltip("How much spin is affected by ground contact")]
48	    public float spinBounceEffect = 0.5f;
49	
50	    [Header("Visual Effects")]
51	    [Tooltip("How much the ball visually rotates based on spin (purely cosmetic)")]
52	    public float visualSpinMultiplier = 2.0f; // Reduced from 5.0 for more realistic visual spin
53	
54	    [Tooltip("How much the ball visually rotates based on rolling (purely cosmetic)")]
55	    public float visualRollMultiplier = 1.0f;
56	
57	    [Header("Auto Reset")]
58	    [Tooltip("Time in seconds before ball auto-resets after being hit (0 = disabled)")]
59	    public float autoResetTime = 8f; // Simple 8-second timer from ball hit
60	
61	    [Tooltip("Reference to GoalDetector for triggering resets")]
62	    public GoalDetector goalDetector;
63	
64	    Rigidbody rb;
65	
66	    // Store spin data for Magnus effect calculation
67	    private Vector3 currentSpin = Vector3.zero;
68	
69	    // Bounce tracking
70	    private bool wasAirborne = false;
71	    private Vector3 lastVelocity = Vector3.zero;
72	
73	    // Visual rotation tracking
74	    private Vector3 visualRotation = Vector3.zero;
75	
76	    // Auto-reset tracking
77	    private float timeSinceHit = 0f;
78	    private bool hasBeenHit = false;
79	    private bool resetTriggered = false; // Prevent multiple reset calls
80	
81	    // External concurrent queue filled by your network listener
82	    public ConcurrentQueue<HitData> hitQueue;
83	
84	    void Awake()
85	    {
86	        rb = GetComponent<Rigidbody>();
87	        if (hitQueue == null)
88	            hitQueue = new ConcurrentQueue<HitData>();
89	    }
90	
91	    void FixedUpdate()
92	    {
93	        // Store velocity for bounce detection
94	        lastVelocity = rb.linearVelocity;
95	
96	        // 1) Apply any queued hits (instant changes coming from simulator)
97	        while (hitQueue != null && hitQueue.TryDequeue(out HitData hit))
98	        {
99	            ApplyHit(hit);
100	        }
101	
102	        // 2) Check for bounces
103	        CheckForBounce();
104	
105	        // 3) Apply physics decay (air resistance, ground friction, spin decay)
106	        ApplyPhysicsDecay();
107	
108	        // 4) Apply Magnus effect each physics step (if there is spin AND velocity)
109	        ApplyMagnus();
110	
111	        // 5) Apply visual rotation (cosmetic only)
112	        ApplyVisualRotation();
113	
114	        // 6) Check for auto-reset if ball has been stationary too long
115	        CheckAutoReset();
116	    }
117	
118	    void ApplyHit(HitData hit)
119	    {
120	        // direction
121	        Vector3 dir = Vector3.forward;
122	        if (hit.dir != null && hit.dir.Length >= 3)
123	            dir = new Vector3(hit.dir[0], hit.dir[1], hit.dir[2]);
124	
125	        if (dir.sqrMagnitude < 1e-6f)
126	        {
127	            dir = Vector3.forward; // Use world forward instead of transform.forward
128	        }
129	        dir.Normalize();
130	
131	        // speed mapping
132	        float speed = Mathf.Clamp01(hit.speed_norm) * maxSpeed;
133	
134	        // either overwrite velocity (best for deterministic simulator input)
135	        if (overwriteVelocity)
136	        {
137	            rb.linearVelocity = dir * speed;
138	        }
139	        else
140	        {
141	            Vector3 impulse = dir * speed * rb.mass;
142	            rb.AddForce(impulse, ForceMode.Impulse);
143	        }
144	
145	        // Store spin data for Magnus effect (but don't apply as angular velocity)
146	        Vector3 spinVec = Vector3.zero;
147	        if (hit.spin != null && hit.spin.Length == 3)
148	            spinVec = new Vector3(hit.spin[0], hit.spin[1], hit.spin[2]);
149	
150	        // Store the spin for Magnus effect calculation
151	        currentSpin = spinVec;
152	
153	        // Mark that ball has been hit (for auto-reset tracking)
154	        hasBeenHit = true;
155	        timeSinceHit = 0f; // Reset timer since hit
156	        resetTriggered = false; // Reset flag for new shot
157	
158	        // DON'T apply spin as angular velocity - this was causing the circular motion
159	        // We'll use the spin data in the Magnus effect calculation instead
160	
161	        // Optional: latency compensation by moving ball forward along velocity (requires synced timestamps)
162	        // if (hit.timestamp > 0) { ... }
163	    }
164	
165	    void ApplyMagnus()
166	    {
167	        // Use stored spin data instead of angular velocity for Magnus effect
168	        Vector3 omega = currentSpin; // Use the spin from the hit data
169	        Vector3 v = rb.linearVelocity;
170	
171	        if (omega.sqrMagnitude > 1e-6f && v.sqrMagnitude > 1e-6f)
172	        {
173	            // Magnus force: F_magnus = magnusFactor * (omega x v)
174	            // For Y-axis spin (curve left/right): omega.y creates force in X direction
175	            Vector3 magnus = Vector3.Cross(omega, v) * magnusFactor;
176	            rb.AddForce(magnus, magnusForceMode);
177	        }
178	    }
179	
180	    void ApplyPhysicsDecay()
181	    {
182	        // Check if ball is on ground or in air
183	        bool onGround = IsOnGround();
184	
185	        // Apply velocity decay
186	        Vector3 currentVelocity = rb.linearVelocity;
187	        float currentSpeed = currentVelocity.magnitude;
188	
189	        // Don't apply physics if ball is kinematic (being held by goalkeeper)
190	        if (!rb.isKinematic)
191	        {
192	            if (currentSpeed > minVelocityThreshold)
193	            {
194	                // Simple velocity decay - much more predictable
195	                float decayRate = onGround ? groundFriction : airDrag;
196	                Vector3 newVelocity = currentVelocity * (1f - decayRate * Time.fixedDeltaTime);
197	                rb.linearVelocity = newVelocity;
198	            }
199	            else
200	            {
201	                // Stop the ball if velocity is below threshold
202	                rb.linearVelocity = Vector3.zero;
203	            }
204	        }
205	
206	        // Apply spin decay over time
207	        if (currentSpin.sqrMagnitude > 1e-6f)
208	        {
209	            float decayRate = onGround ? spinDecay * 2f : spinDecay; // Spin decays faster on ground
210	            currentSpin = Vector3.Lerp(currentSpin, Vector3.zero, decayRate * Time.fixedDeltaTime);
211	
212	            // Stop spin if it's very low
213	            if (currentSpin.sqrMagnitude < 0.01f)
214	            {
215	                currentSpin = Vector3.zero;
216	            }
217	        }
218	    }
219	
220	    bool IsOnGround()
221	    {
222	        // Cast a ray downward to check if ball is close to ground
223	        RaycastHit hit;
224	        Vector3 rayStart = transform.position;
225	        Vector3 rayDirection = Vector3.down;
226	
227	        // Use the ball's collider radius if available, otherwise use groundCheckDistance
228	        float rayDistance = groundCheckDistance;
229	        Collider ballCollider = GetComponent<Collider>();
230	        if (ballCollider is SphereCollider sphereCol)
231	        {
232	            rayDistance = sphereCol.radius + groundCheckDistance;
233	        }
234	
235	        bool isGrounded = Physics.Raycast(rayStart, rayDirection, out hit, rayDistance);
236	
237	        // Optional: Draw debug ray in Scene view
238	        Debug.DrawRay(rayStart, rayDirection * rayDistance, isGrounded ? Color.green : Color.red);
239	
240	        return isGrounded;
241	    }
242	
243	    void CheckForBounce()
244	    {
245	        bool currentlyGrounded = IsOnGround();
246	
247	        // Detect bounce: was airborne, now grounded, and has significant downward velocity
248	        if (wasAirborne && currentlyGrounded && lastVelocity.y < -minBounceVelocity)
249	        {
250	            ApplyBounce();
251	        }
252	
253	        // Update airborne state for next frame
254	        wasAirborne = !currentlyGrounded;
255	    }
256	
257	    void ApplyBounce()
258	    {
259	        Vector3 velocity = rb.linearVelocity;
260	
261	        // Separate horizontal and vertical components
262	        Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
263	        float verticalVelocity = velocity.y;
264	
265	        // Apply bounce to vertical component (reverse and reduce)
266	        float newVerticalVelocity = -verticalVelocity * bounceCoefficient;
267	
268	        // Apply damping to horizontal component (surface friction)
269	        Vector3 newHorizontalVelocity = horizontalVelocity * horizontalDamping;
270	
271	        // Combine and apply new velocity
272	        Vector3 newVelocity = new Vector3(newHorizontalVelocity.x, newVerticalVelocity, newHorizontalVelocity.z);
273	        rb.linearVelocity = newVelocity;
274	
275	        // Apply spin effects from bounce
276	        if (currentSpin.sqrMagnitude > 1e-6f)
277	        {
278	            // Reduce spin magnitude
279	            currentSpin *= spinBounceEffect;
280	
281	            // Backspin can add to bounce height, topspin reduces it
282	            if (currentSpin.x != 0) // X-axis spin affects bounce
283	            {
284	                float spinEffect = currentSpin.x * 0.5f; // Backspin = positive X
285	                rb.linearVelocity = new Vector3(newVelocity.x, newVelocity.y + spinEffect, newVelocity.z);
286	            }
287	        }
288	    }
289	
290	    void ApplyVisualRotation()
291	    {
292	        Vector3 velocity = rb.linearVelocity;
293	        bool onGround = IsOnGround();
294	
295	        // Calculate visual rotation based on ball movement and spin
296	        Vector3 rotationThisFrame = Vector3.zero;
297	
298	        if (onGround && velocity.sqrMagnitude > 0.1f)
299	        {
300	            // Ball is rolling on ground - calculate rotation based on movement
301	            float ballRadius = 0.11f; // Standard soccer ball radius in meters
302	            Collider ballCollider = GetComponent<Collider>();
303	            if (ballCollider is SphereCollider sphereCol)
304	            {
305	                ballRadius = sphereCol.radius * transform.localScale.x; // Account for scale
306	            }
307	
308	            // Rolling rotation: distance / radius = angle in radians
309	            Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
310	            float rollSpeed = horizontalVelocity.magnitude;
311	            float rollAngle = (rollSpeed * Time.fixedDeltaTime) / ballRadius * Mathf.Rad2Deg;
312	
313	            // Roll around X-axis for forward/backward movement, Z-axis for left/right
314	            Vector3 rollAxis = Vector3.Cross(Vector3.up, horizontalVelocity.normalized);
315	            rotationThisFrame += rollAxis * rollAngle * visualRollMultiplier;
316	        }
317	
318	        // Add spin-based rotation (works both in air and on ground)
319	        if (currentSpin.sqrMagnitude > 1e-6f)
320	        {
321	            // Convert spin (rad/s) to degrees/frame
322	            Vector3 spinRotation = currentSpin * Mathf.Rad2Deg * Time.fixedDeltaTime * visualSpinMultiplier;
323	            rotationThisFrame += spinRotation;
324	        }
325	
