using UnityEngine;
using System.Collections.Concurrent;

[RequireComponent(typeof(Rigidbody))]
public class BallController : MonoBehaviour
{
    [Header("Speed / spin mapping")]
    public float maxSpeed = 20f; // m/s when speed_norm == 1
    public bool overwriteVelocity = true;      // if true sets rb.velocity directly; otherwise AddForce impulse

    [Header("Magnus (curve)")]
    [Tooltip("Magnus force scale. Increase to get stronger curve. Typical starting value: 0.2 - 2.0")]
    public float magnusFactor = 0.1f; // Reduced from 0.3f - less extreme curves

    [Tooltip("Apply Magnus as Force (continuous) or Impulse (single big push)")]
    public ForceMode magnusForceMode = ForceMode.Force;

    [Header("Physics Decay")]
    [Tooltip("Air resistance coefficient - reduces velocity over time when airborne")]
    public float airDrag = 0.05f; // Simple percentage per second (5% per second)

    [Tooltip("Ground friction coefficient - reduces velocity when ball is on ground")]
    public float groundFriction = 0.2f; // Simple percentage per second (20% per second)

    [Tooltip("Linear drag coefficient - helps ball stop at low speeds")]
    public float linearDrag = 0.02f; // Not used in simplified system

    [Tooltip("Spin decay rate - how quickly spin reduces over time")]
    public float spinDecay = 0.8f; // per second - reduced from 0.8 for longer lasting spin

    [Tooltip("Ground contact detection - how close to ground counts as 'on ground'")]
    public float groundCheckDistance = 0.1f;

    [Tooltip("Minimum velocity before ball stops completely")]
    public float minVelocityThreshold = 0.01f; // When below this, ball velocity is set to zero

    [Header("Bounce Physics")]
    [Tooltip("How much velocity is retained after bouncing (0 = no bounce, 1 = perfect bounce)")]
    public float bounceCoefficient = 0.3f; // Reduced from 0.6f for less bouncy net interaction

    [Tooltip("Minimum vertical velocity needed to trigger a bounce")]
    public float minBounceVelocity = 2f;

    [Tooltip("How much horizontal velocity is retained during bounce (surface friction)")]
    public float horizontalDamping = 0.4f; // Reduced from 0.8f for more friction with net

    [Tooltip("How much spin is affected by ground contact")]
    public float spinBounceEffect = 0.5f;

    [Header("Visual Effects")]
    [Tooltip("How much the ball visually rotates based on spin (purely cosmetic)")]
    public float visualSpinMultiplier = 2.0f; // Reduced from 5.0 for more realistic visual spin

    [Tooltip("How much the ball visually rotates based on rolling (purely cosmetic)")]
    public float visualRollMultiplier = 1.0f;

    [Header("Auto Reset")]
    [Tooltip("Time in seconds before ball auto-resets after being hit (0 = disabled)")]
    public float autoResetTime = 8f; // Simple 8-second timer from ball hit

    [Tooltip("Reference to GoalDetector for triggering resets")]
    public GoalDetector goalDetector;

    Rigidbody rb;

    // Store spin data for Magnus effect calculation
    private Vector3 currentSpin = Vector3.zero;

    // Bounce tracking
    private bool wasAirborne = false;
    private Vector3 lastVelocity = Vector3.zero;

    // Visual rotation tracking
    private Vector3 visualRotation = Vector3.zero;

    // Auto-reset tracking
    private float timeSinceHit = 0f;
    private bool hasBeenHit = false;
    private bool resetTriggered = false; // Prevent multiple reset calls

    // External concurrent queue filled by your network listener
    public ConcurrentQueue<HitData> hitQueue;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        if (hitQueue == null)
            hitQueue = new ConcurrentQueue<HitData>();
    }

    void FixedUpdate()
    {
        // Store velocity for bounce detection
        lastVelocity = rb.linearVelocity;

        // 1) Apply any queued hits (instant changes coming from simulator)
        while (hitQueue != null && hitQueue.TryDequeue(out HitData hit))
        {
            ApplyHit(hit);
        }

        // 2) Check for bounces
        CheckForBounce();

        // 3) Apply physics decay (air resistance, ground friction, spin decay)
        ApplyPhysicsDecay();

        // 4) Apply Magnus effect each physics step (if there is spin AND velocity)
        ApplyMagnus();

        // 5) Apply visual rotation (cosmetic only)
        ApplyVisualRotation();

        // 6) Check for auto-reset if ball has been stationary too long
        CheckAutoReset();
    }

    void ApplyHit(HitData hit)
    {
        // direction
        Vector3 dir = Vector3.forward;
        if (hit.dir != null && hit.dir.Length >= 3)
            dir = new Vector3(hit.dir[0], hit.dir[1], hit.dir[2]);

        if (dir.sqrMagnitude < 1e-6f)
        {
            dir = Vector3.forward; // Use world forward instead of transform.forward
        }
        dir.Normalize();

        // speed mapping
        float speed = Mathf.Clamp01(hit.speed_norm) * maxSpeed;

        // either overwrite velocity (best for deterministic simulator input)
        if (overwriteVelocity)
        {
            rb.linearVelocity = dir * speed;
        }
        else
        {
            Vector3 impulse = dir * speed * rb.mass;
            rb.AddForce(impulse, ForceMode.Impulse);
        }

        // Store spin data for Magnus effect (but don't apply as angular velocity)
        Vector3 spinVec = Vector3.zero;
        if (hit.spin != null && hit.spin.Length == 3)
            spinVec = new Vector3(hit.spin[0], hit.spin[1], hit.spin[2]);

        // Store the spin for Magnus effect calculation
        currentSpin = spinVec;

        // Mark that ball has been hit (for auto-reset tracking)
        hasBeenHit = true;
        timeSinceHit = 0f; // Reset timer since hit
        resetTriggered = false; // Reset flag for new shot

        // DON'T apply spin as angular velocity - this was causing the circular motion
        // We'll use the spin data in the Magnus effect calculation instead

        // Optional: latency compensation by moving ball forward along velocity (requires synced timestamps)
        // if (hit.timestamp > 0) { ... }
    }

    void ApplyMagnus()
    {
        // Use stored spin data instead of angular velocity for Magnus effect
        Vector3 omega = currentSpin; // Use the spin from the hit data
        Vector3 v = rb.linearVelocity;

        if (omega.sqrMagnitude > 1e-6f && v.sqrMagnitude > 1e-6f)
        {
            // Magnus force: F_magnus = magnusFactor * (omega x v)
            // For Y-axis spin (curve left/right): omega.y creates force in X direction
            Vector3 magnus = Vector3.Cross(omega, v) * magnusFactor;
            rb.AddForce(magnus, magnusForceMode);
        }
    }

    void ApplyPhysicsDecay()
    {
        // Check if ball is on ground or in air
        bool onGround = IsOnGround();

        // Apply velocity decay
        Vector3 currentVelocity = rb.linearVelocity;
        float currentSpeed = currentVelocity.magnitude;

        // Don't apply physics if ball is kinematic (being held by goalkeeper)
        if (!rb.isKinematic)
        {
            if (currentSpeed > minVelocityThreshold)
            {
                // Simple velocity decay - much more predictable
                float decayRate = onGround ? groundFriction : airDrag;
                Vector3 newVelocity = currentVelocity * (1f - decayRate * Time.fixedDeltaTime);
                rb.linearVelocity = newVelocity;
            }
            else
            {
                // Stop the ball if velocity is below threshold
                rb.linearVelocity = Vector3.zero;
            }
        }

        // Apply spin decay over time
        if (currentSpin.sqrMagnitude > 1e-6f)
        {
            float decayRate = onGround ? spinDecay * 2f : spinDecay; // Spin decays faster on ground
            currentSpin = Vector3.Lerp(currentSpin, Vector3.zero, decayRate * Time.fixedDeltaTime);

            // Stop spin if it's very low
            if (currentSpin.sqrMagnitude < 0.01f)
            {
                currentSpin = Vector3.zero;
            }
        }
    }

    bool IsOnGround()
    {
        // Cast a ray downward to check if ball is close to ground
        RaycastHit hit;
        Vector3 rayStart = transform.position;
        Vector3 rayDirection = Vector3.down;

        // Use the ball's collider radius if available, otherwise use groundCheckDistance
        float rayDistance = groundCheckDistance;
        Collider ballCollider = GetComponent<Collider>();
        if (ballCollider is SphereCollider sphereCol)
        {
            rayDistance = sphereCol.radius + groundCheckDistance;
        }

        bool isGrounded = Physics.Raycast(rayStart, rayDirection, out hit, rayDistance);

        // Optional: Draw debug ray in Scene view
        Debug.DrawRay(rayStart, rayDirection * rayDistance, isGrounded ? Color.green : Color.red);

        return isGrounded;
    }

    void CheckForBounce()
    {
        bool currentlyGrounded = IsOnGround();

        // Detect bounce: was airborne, now grounded, and has significant downward velocity
        if (wasAirborne && currentlyGrounded && lastVelocity.y < -minBounceVelocity)
        {
            ApplyBounce();
        }

        // Update airborne state for next frame
        wasAirborne = !currentlyGrounded;
    }

    void ApplyBounce()
    {
        Vector3 velocity = rb.linearVelocity;

        // Separate horizontal and vertical components
        Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
        float verticalVelocity = velocity.y;

        // Apply bounce to vertical component (reverse and reduce)
        float newVerticalVelocity = -verticalVelocity * bounceCoefficient;

        // Apply damping to horizontal component (surface friction)
        Vector3 newHorizontalVelocity = horizontalVelocity * horizontalDamping;

        // Combine and apply new velocity
        Vector3 newVelocity = new Vector3(newHorizontalVelocity.x, newVerticalVelocity, newHorizontalVelocity.z);
        rb.linearVelocity = newVelocity;

        // Apply spin effects from bounce
        if (currentSpin.sqrMagnitude > 1e-6f)
        {
            // Reduce spin magnitude
            currentSpin *= spinBounceEffect;

            // Backspin can add to bounce height, topspin reduces it
            if (currentSpin.x != 0) // X-axis spin affects bounce
            {
                float spinEffect = currentSpin.x * 0.5f; // Backspin = positive X
                rb.linearVelocity = new Vector3(newVelocity.x, newVelocity.y + spinEffect, newVelocity.z);
            }
        }
    }

    void ApplyVisualRotation()
    {
        Vector3 velocity = rb.linearVelocity;
        bool onGround = IsOnGround();

        // Calculate visual rotation based on ball movement and spin
        Vector3 rotationThisFrame = Vector3.zero;

        if (onGround && velocity.sqrMagnitude > 0.1f)
        {
            // Ball is rolling on ground - calculate rotation based on movement
            float ballRadius = 0.11f; // Standard soccer ball radius in meters
            Collider ballCollider = GetComponent<Collider>();
            if (ballCollider is SphereCollider sphereCol)
            {
                ballRadius = sphereCol.radius * transform.localScale.x; // Account for scale
            }

            // Rolling rotation: distance / radius = angle in radians
            Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
            float rollSpeed = horizontalVelocity.magnitude;
            float rollAngle = (rollSpeed * Time.fixedDeltaTime) / ballRadius * Mathf.Rad2Deg;

            // Roll around X-axis for forward/backward movement, Z-axis for left/right
            Vector3 rollAxis = Vector3.Cross(Vector3.up, horizontalVelocity.normalized);
            rotationThisFrame += rollAxis * rollAngle * visualRollMultiplier;
        }

        // Add spin-based rotation (works both in air and on ground)
        if (currentSpin.sqrMagnitude > 1e-6f)
        {
            // Convert spin (rad/s) to degrees/frame
            Vector3 spinRotation = currentSpin * Mathf.Rad2Deg * Time.fixedDeltaTime * visualSpinMultiplier;
            rotationThisFrame += spinRotation;
        }

        // Apply the rotation to the transform
        if (rotationThisFrame.sqrMagnitude > 1e-6f)
        {
            transform.Rotate(rotationThisFrame, Space.World);
        }
    }

    void CheckAutoReset()
    {
        // Only check for auto-reset if the feature is enabled and ball has been hit
        if (autoResetTime <= 0f)
        {
            return;
        }

        if (!hasBeenHit)
        {
            return;
        }

        // Always increment timer after ball has been hit, regardless of movement
        timeSinceHit += Time.fixedDeltaTime;

        // If enough time has passed since hit, trigger reset (only once)
        if (timeSinceHit >= autoResetTime && !resetTriggered)
        {
            resetTriggered = true; // Mark reset as triggered to prevent multiple calls
            TriggerAutoReset();
        }
    }

    void TriggerAutoReset()
    {
        if (goalDetector != null)
        {
            goalDetector.ManualReset();
        }
        else
        {
            // Fallback: just reset ball position if no GoalDetector reference
            transform.position = Vector3.zero;
            rb.linearVelocity = Vector3.zero;
            rb.angularVelocity = Vector3.zero;
            currentSpin = Vector3.zero;
        }

        // Reset tracking variables
        hasBeenHit = false;
        timeSinceHit = 0f;
    }

    // Public method to reset the auto-reset timer (called when ball is manually reset)
    public void ResetAutoResetTimer()
    {
        hasBeenHit = false;
        timeSinceHit = 0f;
        resetTriggered = false; // Reset flag for next shot
    }
}

// Serializable container for JSON mapping
[System.Serializable]
public class HitData
{
    public double timestamp;   // optional (seconds); you can ignore if you don't use timestamps
    public float[] dir;        // length 3
    public float speed_norm;   // 0..1
    public float[] spin;       // optional length 3 (rad/s suggested)
}

