// SimulatedHitSender.cs
using System.Collections;
using System.Collections.Concurrent;
using UnityEngine;

public class SimulatedHitSender : MonoBehaviour
{
    [Tooltip("Assign your ball's BallController here")]
    public BallController ballController;

    [Tooltip("If true, automatically send sample hits on Start")]
    public bool autoSendOnStart = true;

    [Tooltip("Delay between auto-sent hits")]
    public float delayBetweenHits = 5.0f;

    void Start()
    {
        if (autoSendOnStart)
            StartCoroutine(AutoSendRoutine());
    }

    IEnumerator AutoSendRoutine()
    {
        // Wait a moment to ensure everything is initialized
        yield return new WaitForSeconds(2f);

        // Right-Center low shot
        Vector3 dir6 = new Vector3(0.5f, 0.5f, 5f); // Right-center low shot
        SendHitRPS(dir6, 0.9f, new Vector3(0f, 0f, 0f));
        yield return new WaitForSeconds(delayBetweenHits);

        // Center shot (straight and fast)
        Vector3 dir3 = new Vector3(0f, 1.5f, 5f); // High center shot
        SendHitRPS(dir3, 0.95f, Vector3.zero); // No spin, straight shot
        yield return new WaitForSeconds(delayBetweenHits);

        // High right corner with topspin (dips down)
        Vector3 dir5 = new Vector3(1.7f, 4f, 5f); // High right shot
        SendHitRPS(dir5, 0.85f, new Vector3(0.5f, 0f, 0f)); // Topspin for dip
        yield return new WaitForSeconds(delayBetweenHits);

        // Right side curved shot
        Vector3 dir1 = new Vector3(3f, 2f, 5f); // Right side shot
        SendHitRPS(dir1, 0.85f, new Vector3(0f, -0.5f, 0f)); // Right curve (negative Y spin)
        yield return new WaitForSeconds(delayBetweenHits);

        // Left side straight shot
        Vector3 dir2 = new Vector3(-1.5f, 2f, 5f); // Left side shot
        SendHitRPS(dir2, 0.9f, new Vector3(0f, 0f, 0f)); // No spin for straight shot
        yield return new WaitForSeconds(delayBetweenHits);

        // Low left corner with curve
        Vector3 dir4 = new Vector3(-1.5f, 0.4f, 5f); // Low left shot
        SendHitRPS(dir4, 0.8f, new Vector3(0f, 0.1f, 0f)); // Left curve (positive Y spin)
        yield return new WaitForSeconds(delayBetweenHits);

        // // Backspin (negative X-axis spin) - ball will have more lift
        // SendHitRPS(new Vector3(0f, 0.1f, 1f), 0.85f, new Vector3(-1.0f, 0f, 0f)); // Increased back to -1.0 rps
        // yield return new WaitForSeconds(delayBetweenHits);
    }

    /// <summary>
    /// Public method to send a single simulated hit
    /// </summary>
    /// <param name="direction">world-space direction the ball should travel (will be normalized)</param>
    /// <param name="speedNorm">0..1</param>
    /// <param name="spinRadPerSec">spin vector in rad/s (x,y,z)</param>
    public void SendHit(Vector3 direction, float speedNorm, Vector3 spinRadPerSec)
    {
        // Create HitData matching your BallController's expectations
        HitData hit = new HitData
        {
            timestamp = UnityEngine.Time.time,
            dir = new float[] { direction.x, direction.y, direction.z },
            speed_norm = Mathf.Clamp01(speedNorm),
            spin = new float[] { spinRadPerSec.x, spinRadPerSec.y, spinRadPerSec.z }
        };

        // Ensure ballController & queue exist
        if (ballController == null)
        {
            return;
        }
        if (ballController.hitQueue == null)
            ballController.hitQueue = new ConcurrentQueue<HitData>();

        // Enqueue the simulated hit (just like the UdpReceiver would)
        ballController.hitQueue.Enqueue(hit);
    }

    // Convenience wrapper that converts spin in revolutions-per-second (rps) to rad/s
    public void SendHitRPS(Vector3 direction, float speedNorm, Vector3 spinRps)
    {
        const float twoPi = 2f * Mathf.PI;
        Vector3 spinRad = spinRps * twoPi;
        SendHit(direction, speedNorm, spinRad);
    }

    // Expose a Context menu action for quick manual testing in the Editor (right-click the component)
    [ContextMenu("Send Quick Test Hit (straight)")]
    void ContextSendQuick()
    {
        SendHit(Vector3.forward, 0.8f, Vector3.zero);
    }
}

