    {
        // Drain all frames that arrived since last iteration
        DetectionResult? det0 = null, det1 = null;
        CameraFrame? rectFrame0 = null, rectFrame1 = null;

        while (_cameras.FrameQueue.TryTake(out var frame, 5))
        {
