3	public class GoalDetector : MonoBehaviour
4	{
5	    [Header("Goal Detection Settings")]
6	    [Tooltip("Tag to identify the ball (should be 'Ball' or whatever tag your ball has)")]
7	    public string ballTag = "Ball";
8	
9	    [Header("Goal Events")]
10	    [Tooltip("Optional: assign a GameObject to activate when goal is scored (like celebration effects)")]
11	    public GameObject goalEffectObject;
12	
13	    [Tooltip("Optional: assign an AudioSource to play goal sound")]
14	    public AudioSource goalAudioSource;
15	
16	    [Header("Reset References")]
17	    [Tooltip("Assign the goalkeeper GameObject to reset its position and animation")]
18	    public GameObject goalkeeper;
19	
20	    private bool goalScored = false;
21	    private Vector3 originalGoalkeeperPosition;
22	    private Quaternion originalGoalkeeperRotation;
23	
24	    void Start()
25	    {
26	        // Store the original goalkeeper position and rotation
27	        if (goalkeeper != null)
28	        {
29	            originalGoalkeeperPosition = goalkeeper.transform.position;
30	            originalGoalkeeperRotation = goalkeeper.transform.rotation;
31	        }
32	    }
33	
34	    void OnTriggerEnter(Collider other)
35	    {
36	        // Check if the ball entered the goal
37	        if (other.CompareTag(ballTag) && !goalScored)
38	        {
39	            goalScored = true;
40	            OnGoalScored(other.gameObject);
41	        }
42	    }
43	
44	    void OnGoalScored(GameObject ball)
45	    {
46	        Debug.Log("GOAL SCORED!");
47	
48	        // Activate goal effects (optional)
49	        if (goalEffectObject != null)
50	        {
51	            goalEffectObject.SetActive(true);
52	        }
53	
54	        // Play goal sound (optional)
55	        if (goalAudioSource != null)
56	        {
57	            goalAudioSource.Play();
58	        }
59	
60	        // Reset after a delay (optional)
61	        Invoke(nameof(ResetGoal), 3f);
62	    }
63	
64	    void ResetGoal()
65	    {
66	        goalScored = false;
67	
68	        // Reset ball position (optional)
69	        GameObject ball = GameObject.FindGameObjectWithTag(ballTag);
70	        if (ball != null)
71	        {
72	            // Stop the ball movement
73	            Rigidbody ballRb = ball.GetComponent<Rigidbody>();
74	            if (ballRb != null)
75	            {
76	                ballRb.linearVelocity = Vector3.zero;
77	                ballRb.angularVelocity = Vector3.zero;
78	            }
79	            ball.transform.position = Vector3.zero; // Reset to starting position
80	            // Clear any queued hits and reset auto-reset timer
81	            BallController ballController = ball.GetComponent<BallController>();
82	            if (ballController != null)
83	            {
84	                // Clear the queue
85	                if (ballController.hitQueue != null)
86	                {
87	                    while (ballController.hitQueue.TryDequeue(out var _)) { }
88	                }
89	                // Reset the auto-reset timer to prevent double resets
90	                ballController.ResetAutoResetTimer();
91	            }
92	        }
93	
94	        // Reset goalkeeper position and animation
95	        ResetGoalkeeper();
96	
97	        // Deactivate goal effects
98	        if (goalEffectObject != null)
99	        {
100	            goalEffectObject.SetActive(false);
101	        }
102	    }
103	
104	    void ResetGoalkeeper()
105	    {
106	        if (goalkeeper != null)
107	        {
108	            // Reset goalkeeper to original position and rotation
109	            goalkeeper.transform.position = originalGoalkeeperPosition;
110	            goalkeeper.transform.rotation = originalGoalkeeperRotation;
111	
112	            // Reset goalkeeper AI state
113	            GoalkeeperAI goalkeeperAI = goalkeeper.GetComponent<GoalkeeperAI>();
114	            if (goalkeeperAI != null)
115	            {
116	                goalkeeperAI.ResetGoalkeeper();
117	            }
118	
119	            // Reset animator to idle state
120	            Animator goalkeeperAnimator = goalkeeper.GetComponent<Animator>();
121	            if (goalkeeperAnimator != null)
122	            {
123	                goalkeeperAnimator.SetInteger("SaveType", 0); // Reset to idle
124	                goalkeeperAnimator.SetBool("HasBall", false); // Ensure not holding ball
125	                goalkeeperAnimator.SetTrigger("Reset"); // Trigger Any State → Idle transition
126	                goalkeeperAnimator.ResetTrigger("ShouldSave"); // Clear any pending save triggers
127	            }
128	        }
129	    }
130	
131	    // Public method to manually reset (called by BallController 8-second timer)
132	    public void ManualReset()
133	    {
134	        ResetGoal();
