using UnityEngine;

public class GoalDetector : MonoBehaviour
{
    [Header("Goal Detection Settings")]
    [Tooltip("Tag to identify the ball (should be 'Ball' or whatever tag your ball has)")]
    public string ballTag = "Ball";

    [Header("Goal Events")]
    [Tooltip("Optional: assign a GameObject to activate when goal is scored (like celebration effects)")]
    public GameObject goalEffectObject;

    [Tooltip("Optional: assign an AudioSource to play goal sound")]
    public AudioSource goalAudioSource;

    [Header("Reset References")]
    [Tooltip("Assign the goalkeeper GameObject to reset its position and animation")]
    public GameObject goalkeeper;

    private bool goalScored = false;
    private Vector3 originalGoalkeeperPosition;
    private Quaternion originalGoalkeeperRotation;

    void Start()
    {
        // Store the original goalkeeper position and rotation
        if (goalkeeper != null)
        {
            originalGoalkeeperPosition = goalkeeper.transform.position;
            originalGoalkeeperRotation = goalkeeper.transform.rotation;
        }
    }

    void OnTriggerEnter(Collider other)
    {
        // Check if the ball entered the goal
        if (other.CompareTag(ballTag) && !goalScored)
        {
            goalScored = true;
            OnGoalScored(other.gameObject);
        }
    }

    void OnGoalScored(GameObject ball)
    {
        Debug.Log("GOAL SCORED!");

        // Activate goal effects (optional)
        if (goalEffectObject != null)
        {
            goalEffectObject.SetActive(true);
        }

        // Play goal sound (optional)
        if (goalAudioSource != null)
        {
            goalAudioSource.Play();
        }

        // Reset after a delay (optional)
        Invoke(nameof(ResetGoal), 3f);
    }

    void ResetGoal()
    {
        goalScored = false;

        // Reset ball position (optional)
        GameObject ball = GameObject.FindGameObjectWithTag(ballTag);
        if (ball != null)
        {
            // Stop the ball movement
            Rigidbody ballRb = ball.GetComponent<Rigidbody>();
            if (ballRb != null)
            {
                ballRb.linearVelocity = Vector3.zero;
                ballRb.angularVelocity = Vector3.zero;
            }
            ball.transform.position = Vector3.zero; // Reset to starting position
            // Clear any queued hits and reset auto-reset timer
            BallController ballController = ball.GetComponent<BallController>();
            if (ballController != null)
            {
                // Clear the queue
                if (ballController.hitQueue != null)
                {
                    while (ballController.hitQueue.TryDequeue(out var _)) { }
                }
                // Reset the auto-reset timer to prevent double resets
                ballController.ResetAutoResetTimer();
            }
        }

        // Reset goalkeeper position and animation
        ResetGoalkeeper();

        // Deactivate goal effects
        if (goalEffectObject != null)
        {
            goalEffectObject.SetActive(false);
        }
    }

    void ResetGoalkeeper()
    {
        if (goalkeeper != null)
        {
            // Reset goalkeeper to original position and rotation
            goalkeeper.transform.position = originalGoalkeeperPosition;
            goalkeeper.transform.rotation = originalGoalkeeperRotation;

            // Reset goalkeeper AI state
            GoalkeeperAI goalkeeperAI = goalkeeper.GetComponent<GoalkeeperAI>();
            if (goalkeeperAI != null)
            {
                goalkeeperAI.ResetGoalkeeper();
            }

            // Reset animator to idle state
            Animator goalkeeperAnimator = goalkeeper.GetComponent<Animator>();
            if (goalkeeperAnimator != null)
            {
                goalkeeperAnimator.SetInteger("SaveType", 0); // Reset to idle
                goalkeeperAnimator.SetBool("HasBall", false); // Ensure not holding ball
                goalkeeperAnimator.SetTrigger("Reset"); // Trigger Any State → Idle transition
                goalkeeperAnimator.ResetTrigger("ShouldSave"); // Clear any pending save triggers
            }
        }
    }

    // Public method to manually reset (called by BallController 8-second timer)
    public void ManualReset()
    {
        ResetGoal();
    }
}

