using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;
using UnityEngine;

// Receives BallData packets from the accugolfmiddleware simulator process.
// Wire format (Transport/PacketSerializer.cs in the middleware repo):
//   [1 byte PacketType][4 bytes little-endian JSON length][N bytes JSON]
// PacketType 0x01 = BallData. Middleware sends to this port by default
// (see App/Program.cs: sendPort defaults to 7100).
public class UdpReceiverNew : MonoBehaviour
{
    public int listenPort = 7100;
    public BallController ballController;  // assign this in the Inspector!

    [Tooltip("Divide SpinRpm axis vector into rad/s and feed it to BallController's Magnus effect. Axis is currently camera-relative (see notes/14-session-2026-07-22-hardware-bringup.md) — disable if it looks wrong on real shots.")]
    public bool applySpin = true;

    private UdpClient udpClient;
    private Thread receiveThread;
    private volatile bool running;

    const byte BallDataPacketType = 0x01;

    void Start()
    {
        if (ballController == null)
        {
            Debug.LogError("[UDP] UdpReceiverNew has no BallController assigned.");
            return;
        }

        if (ballController.hitQueue == null)
            ballController.hitQueue = new ConcurrentQueue<HitData>();

        udpClient = new UdpClient(listenPort);
        running = true;

        receiveThread = new Thread(ReceiveLoop);
        receiveThread.IsBackground = true;
        receiveThread.Start();

        Debug.Log($"[UDP] Listening for middleware BallData on port {listenPort}");
    }

    void ReceiveLoop()
    {
        IPEndPoint remoteEndPoint = new IPEndPoint(IPAddress.Any, listenPort);
        while (running)
        {
            try
            {
                byte[] raw = udpClient.Receive(ref remoteEndPoint);
                HandlePacket(raw);
            }
            catch (SocketException)
            {
                break; // happens when closing the socket
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[UDP] Error: " + ex.Message);
            }
        }
    }

    void HandlePacket(byte[] raw)
    {
        if (raw.Length < 5)
        {
            Debug.LogWarning($"[UDP] Packet too short ({raw.Length} bytes)");
            return;
        }

        byte packetType = raw[0];
        int length = BitConverter.ToInt32(raw, 1);
        if (length < 0 || 5 + length > raw.Length)
        {
            Debug.LogWarning($"[UDP] Packet length header ({length}) doesn't match payload ({raw.Length - 5} bytes available)");
            return;
        }

        if (packetType != BallDataPacketType)
            return; // ProfileCommand (0x10) etc. — not consumed here

        string json = Encoding.UTF8.GetString(raw, 5, length);
        MiddlewareBallData data;
        try
        {
            data = JsonUtility.FromJson<MiddlewareBallData>(json);
        }
        catch (Exception ex)
        {
            Debug.LogWarning("[UDP] Failed to parse BallData JSON: " + ex.Message + " -- " + json);
            return;
        }

        HitData hit = ToHitData(data);
        ballController.hitQueue.Enqueue(hit);
    }

    HitData ToHitData(MiddlewareBallData data)
    {
        Vector3 velocity = new Vector3(data.VelX, data.VelY, data.VelZ);
        Vector3 dir = velocity.sqrMagnitude > 1e-6f ? velocity.normalized : Vector3.forward;

        Vector3 spin = Vector3.zero;
        if (applySpin && data.SpinRpm > 0f)
        {
            Vector3 axis = new Vector3(data.SpinAxisX, data.SpinAxisY, data.SpinAxisZ);
            if (axis.sqrMagnitude > 1e-6f)
            {
                float radPerSec = data.SpinRpm * 2f * Mathf.PI / 60f;
                spin = axis.normalized * radPerSec;
            }
        }

        return new HitData
        {
            timestamp = data.TimestampUs / 1_000_000.0,
            dir = new float[] { dir.x, dir.y, dir.z },
            speedMps = data.SpeedMps,
            spin = new float[] { spin.x, spin.y, spin.z },
        };
    }

    void OnApplicationQuit()
    {
        running = false;
        udpClient?.Close();
        receiveThread?.Join(200);
    }

    void OnDestroy()
    {
        running = false;
        udpClient?.Close();
    }
}

