using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;
using UnityEngine;

public class UdpReceiverNew : MonoBehaviour
{
    public int listenPort = 5005;  // 👈 this makes it listen on port 5005
    public BallController ballController;  // assign this in the Inspector!

    private UdpClient udpClient;
    private Thread receiveThread;
    private bool running;

    void Start()
    {
        udpClient = new UdpClient(listenPort);  // bind to port 5005
        running = true;

        // make sure BallController has a queue
        if (ballController.hitQueue == null)
            ballController.hitQueue = new ConcurrentQueue<HitData>();

        receiveThread = new Thread(new ThreadStart(ReceiveData));
        receiveThread.IsBackground = true;
        receiveThread.Start();

        Debug.Log($"[UDP] Listening on port {listenPort}");
    }

    void ReceiveData()
    {
        IPEndPoint remoteEndPoint = new IPEndPoint(IPAddress.Any, listenPort);
        while (running)
        {
            try
            {
                byte[] data = udpClient.Receive(ref remoteEndPoint);
                string json = Encoding.UTF8.GetString(data);

                // parse JSON into HitData
                HitData hit = JsonUtility.FromJson<HitData>(json);
                ballController.hitQueue.Enqueue(hit);

                Debug.Log($"[UDP] Received hit from {remoteEndPoint.Address}");
            }
            catch (SocketException)
            {
                // happens when closing
                break;
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[UDP] Error: " + ex.Message);
            }
        }
    }

    void OnApplicationQuit()
    {
        running = false;
        udpClient?.Close();
        receiveThread?.Abort();
    }
}

