2	// Vision/MockCameraManager.cs
3	// ------------------------------------------------------------
4	// Software-only ICameraManager for unit tests.
5	// Generates synthetic stereo frame pairs — two cameras side by side,
6	// each seeing a ball flying along a configurable straight-line trajectory.
7	//
8	// No Spinnaker SDK, no hardware required.
9	//
10	// Usage:
11	//   var mock = new MockCameraManager();
12	//   mock.SetTrajectory(speedMps: 30f, launchAngleDeg: 15f, azimuthDeg: 0f);
13	//   var engine = new SimulatorEngine(mock);
14	// ------------------------------------------------------------
15	using System;
16	using System.Collections.Concurrent;
17	using System.Drawing;
18	using System.Threading;
19	using System.Threading.Tasks;
20	
21	namespace SportSimulator.Vision
22	{
23	    public class MockCameraManager : ICameraManager
24	    {
25	        // ── Camera rig geometry ────────────────────────────────────────────────
26	        // Matches the defaults in StereoCalibrationData.CreateDefaults().
27	        // Two cameras 495.3mm apart (19.5in measured), each with a 1280×1024
28	        // sensor, 8mm focal length.
29	        private const int    SensorW        = 1280;
30	        private const int    SensorH        = 1024;
31	        private const float  FocalPx        = 1800f;   // ≈ 8mm lens at 4.8µm pitch
32	        private const float  BaselineM      = 0.4953f; // metres between cameras (19.5in)
33	        private const float  CamHeightM     = 0.00f;   // cameras at origin height
34	        private const float  BallStartZ     = 0.0f;    // ball starts at camera plane
35	        private const float  BallStartX     = 0.0f;    // centred left-right
36	
37	        // ── Trajectory ────────────────────────────────────────────────────────
38	        private float _speedMps       = 30f;
39	        private float _launchAngleDeg = 15f;
40	        private float _azimuthDeg     = 0f;
41	
42	        // ── Synthetic noise ───────────────────────────────────────────────────
43	        private float _positionNoisePx = 1.5f;   // pixel std-dev per detection
44	        private readonly Random _rng = new(42);  // seeded for reproducibility
45	
46	        // ── Timing ────────────────────────────────────────────────────────────
47	        // Matches the real rig's confirmed default: SpinView reports 199.76fps
48	        // full-frame (see KalmanBallTracker.cs). Reduced-ROI fps is still unmeasured.
49	        private float _fps = 199.76f;
50	
51	        public BlockingCollection<CameraFrame> FrameQueue { get; } = new(256);
52	
53	        private CancellationTokenSource? _cts;
54	        private string _sportId = "generic";
55	
56	        // ── Public API ────────────────────────────────────────────────────────
57	
58	        /// <summary>Configure the simulated ball launch.</summary>
59	        public void SetTrajectory(float speedMps = 30f, float launchAngleDeg = 15f,
60	                                  float azimuthDeg = 0f, float fps = 199.76f,
61	                                  float positionNoisePx = 1.5f)
62	        {
63	            _speedMps        = speedMps;
64	            _launchAngleDeg  = launchAngleDeg;
65	            _azimuthDeg      = azimuthDeg;
66	            _fps             = fps;
67	            _positionNoisePx = positionNoisePx;
68	        }
69	
70	        public void Initialize(string activeSportId = "generic") => _sportId = activeSportId;
71	
72	        public void ApplyProfile(string sportId) => _sportId = sportId;
73	
74	        public void StartCapture()
75	        {
76	            _cts = new CancellationTokenSource();
77	            Task.Factory.StartNew(() => GenerateFrames(_cts.Token),
78	                TaskCreationOptions.LongRunning);
79	        }
80	
81	        public void Stop() => _cts?.Cancel();
82	
83	        public void Dispose() { Stop(); FrameQueue.Dispose(); }
84	
85	        // ── Frame generation ──────────────────────────────────────────────────
86	
87	        private void GenerateFrames(CancellationToken ct)
88	        {
89	            float intervalMs = 1000f / _fps;
90	            int   frameCount = (int)(_fps * 2); // 2 seconds of flight
91	
92	            // Decompose velocity into world components
93	            float launchRad  = _launchAngleDeg * MathF.PI / 180f;
94	            float azimuthRad = _azimuthDeg      * MathF.PI / 180f;
95	            float vz = _speedMps * MathF.Cos(launchRad) * MathF.Cos(azimuthRad);
96	            float vx = _speedMps * MathF.Cos(launchRad) * MathF.Sin(azimuthRad);
97	            float vy = _speedMps * MathF.Sin(launchRad);
98	
99	            float dt    = 1f / _fps;
100	            float bx    = BallStartX;
101	            float by    = CamHeightM;
102	            float bz    = BallStartZ + 0.5f; // start 0.5m in front of cameras
103	
104	            long  timestampUs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() * 1000L;
105	
106	            for (int f = 0; f < frameCount && !ct.IsCancellationRequested; f++)
107	            {
108	                // Advance ball position (gravity on Y)
109	                bx += vx * dt;
110	                by += vy * dt - 0.5f * 9.81f * dt * dt;
111	                bz += vz * dt;
112	                vy -= 9.81f * dt;
113	
114	                // Project onto each camera sensor
115	                // Camera 0: at (-baseline/2, 0, 0)  looking +Z
116	                // Camera 1: at (+baseline/2, 0, 0)  looking +Z
117	                var frame0 = ProjectToCamera(bx + BaselineM / 2f, by, bz, 0, timestampUs);
118	                var frame1 = ProjectToCamera(bx - BaselineM / 2f, by, bz, 1, timestampUs);
119	
120	                if (frame0 != null) FrameQueue.TryAdd(frame0);
121	                if (frame1 != null) FrameQueue.TryAdd(frame1);
122	
123	                timestampUs += (long)(dt * 1_000_000f);
124	                Thread.Sleep((int)intervalMs);
125	            }
126	        }
