141	            if (px < 0 || px >= SensorW || py < 0 || py >= SensorH) return null; // off-sensor
142	
143	            // Build a minimal synthetic frame: black background, white ball blob
144	            int   r      = 6; // radius in pixels
145	            var   data   = new byte[SensorW * SensorH];
146	            int   cx     = (int)px;
147	            int   cy     = (int)py;
148	
149	            for (int dy = -r; dy <= r; dy++)
150	            for (int dx = -r; dx <= r; dx++)
151	            {
152	                if (dx*dx + dy*dy > r*r) continue;
153	                int row = cy + dy, col = cx + dx;
154	                if (row < 0 || row >= SensorH || col < 0 || col >= SensorW) continue;
155	                data[row * SensorW + col] = 255;
156	            }
157	
158	            return new CameraFrame
159	            {
160	                CameraIndex    = camIdx,
161	                Data           = data,
162	                Width          = SensorW,
163	                Height         = SensorH,
164	                TimestampUs    = timestampUs,
165	                ExposureTimeUs = 500.0,
166	                GainDb         = 0.0
167	            };
168	        }
