                var frame1 = ProjectToCamera(bx - BaselineM / 2f, by, bz, 1, timestampUs);

                if (frame0 != null) FrameQueue.TryAdd(frame0);
                if (frame1 != null) FrameQueue.TryAdd(frame1);

                timestampUs += (long)(dt * 1_000_000f);
                Thread.Sleep((int)intervalMs);
            }
