using System;
using System.Net.Sockets;
using System.Text;
using System.Collections;
using UnityEngine;

// Tells the accugolfmiddleware simulator process which sport profile to use,
// so it configures BallDetector's contour-area window, Kalman tuning, and
// exposure map for the right ball (see Profiles/SportProfileRegistry.cs).
//
// Wire format matches Transport/PacketSerializer.cs in the middleware repo:
//   [1 byte PacketType=0x10 (ProfileCommand)][4-byte little-endian JSON length][JSON]
// The middleware listens for this on its `listenPort` (default 7101 — see
// App/Program.cs / SimulatorEngine.Start). This is one-way: the middleware
// applies the profile and does not send an acknowledgement back.
public class ProfileSelectSender : MonoBehaviour
{
    public string middlewareIp = "127.0.0.1";
    public int middlewarePort = 7101;
    public string sportId = "soccer";

    [Tooltip("Resend a few times after Start in case the middleware process starts after Unity does — UDP has no delivery guarantee and this protocol has no ack.")]
    public int retryCount = 5;
    public float retryIntervalSeconds = 2f;

    const byte ProfileCommandPacketType = 0x10;

    UdpClient _client;

    void Start()
    {
        _client = new UdpClient();
        StartCoroutine(SendWithRetries());
    }

    IEnumerator SendWithRetries()
    {
        int attempts = Mathf.Max(1, retryCount);
        for (int i = 0; i < attempts; i++)
        {
            Send(sportId);
            if (i < attempts - 1)
                yield return new WaitForSeconds(retryIntervalSeconds);
        }
    }

    // Call this directly (e.g. from a menu button) to switch sport at runtime.
    public void Send(string sport)
    {
        try
        {
            string json = JsonUtility.ToJson(new ProfileSelectCommand { SportId = sport });
            byte[] payload = Encoding.UTF8.GetBytes(json);
            byte[] packet = new byte[5 + payload.Length];
            packet[0] = ProfileCommandPacketType;
            BitConverter.GetBytes(payload.Length).CopyTo(packet, 1);
            payload.CopyTo(packet, 5);

            _client.Send(packet, packet.Length, middlewareIp, middlewarePort);
            Debug.Log($"[UDP] Sent ProfileSelectCommand '{sport}' to {middlewareIp}:{middlewarePort}");
        }
        catch (Exception ex)
        {
            Debug.LogWarning("[UDP] Failed to send ProfileSelectCommand: " + ex.Message);
        }
    }

    void OnDestroy() => _client?.Close();
    void OnApplicationQuit() => _client?.Close();
}

// Mirrors SportSimulator.Models.ProfileSelectCommand (accugolfmiddleware repo,
// Models/ProfileSelectCommand.cs). Field name/casing must match exactly.
[Serializable]
public class ProfileSelectCommand
{
    public string SportId;
}

