27	        public double[] R  { get; set; } = new double[9];
28	        public double[] T  { get; set; } = new double[3];
29	
30	        // Rectification outputs (computed, not calibrated — filled by StereoRectifier)
31	        public double[] R0 { get; set; } = new double[9];
32	        public double[] R1 { get; set; } = new double[9];
33	        public double[] P0 { get; set; } = new double[12];
34	        public double[] P1 { get; set; } = new double[12];
35	        public double[] Q  { get; set; } = new double[16];  // disparity-to-depth map
36	
37	        public int ImageWidth  { get; set; } = 720;
38	        public int ImageHeight { get; set; } = 540;
39	
40	        // --------------------------------------------------------
41	        // Defaults derived from on-site measurements (2026-07-22), NOT a real
42	        // calibration. REPLACE by running StereoCalibrator with a checkerboard —
43	        // see the class comment above.
44	        // --------------------------------------------------------
45	        public static StereoCalibrationData CreateDefaults(double baselineMetres = 0.4953)
46	        {
47	            // Resolved on-site 2026-07-22:
48	            //
49	            // 1. BASELINE (parameter above, 0.4953m) — 19.5in measured center-to-center.
50	            //
51	            // 2. SENSOR RESOLUTION — confirmed 720×540 (Blackfly S BFS-PGE-04S2M,
52	            //    fixed/locked — no ROI windowing available on this model).
53	            //
54	            // 3. FOV MEASUREMENT — floor footprint measured under the camera's FOV:
55	            //    123.5cm × 98cm. Used here as an approximate frontal-plane width at
56	            //    the slant distance to the ball spot (≈3.015m, from the 114in
57	            //    height / 33in forward-offset mounting geometry) — NOT a rigorous
58	            //    derivation. The floor is a plane tilted ~16° relative to the
59	            //    camera's view axis, so this footprint is really a trapezoid, not
60	            //    a clean frontal rectangle; treating it as one introduces error
61	            //    that grows toward the near/far edges of the visible floor patch.
62	            //    Good enough as a placeholder, not as calibration.
63	            //
64	            // Once StereoCalibrator has been run and stereo_calibration.json exists,
65	            // these defaults are only used as a fallback if the JSON is missing.
66	
67	            const double MEASUREMENT_DISTANCE_M = 3.015; // slant distance, camera to ball spot
68	            const double HALF_WIDTH_M = 0.6175;           // half of the measured 123.5cm floor width
69	
70	            const int IMAGE_WIDTH  = 720;
71	            const int IMAGE_HEIGHT = 540;
72	
73	            double cx = IMAGE_WIDTH  / 2.0;
74	            double cy = IMAGE_HEIGHT / 2.0;
75	
76	            // fx back-calculated from the FOV measurement (horizontal)
77	            double fx = (IMAGE_WIDTH / 2.0) / (HALF_WIDTH_M / MEASUREMENT_DISTANCE_M);
78	
79	            // fy = fx. For a square-pixel sensor (true of virtually all machine-vision
80	            // sensors, including this one), the pixel-to-radian conversion is identical
81	            // in both axes regardless of resolution or aspect ratio — aspect ratio only
82	            // affects cx/cy, not the fx/fy ratio. (The previous `fx * (cy/cx)` formula
83	            // here was wrong: for 1280×1024 it computed fy = 0.8·fx while its own
