using System;
using Emgu.CV;
using Emgu.CV.CvEnum;
using SportSimulator.Profiles;
using SportSimulator.Vision;
using SportSimulator.Vision.Calibration;
using Xunit;
using Xunit.Abstractions;

namespace SportSimulator.Tests
{
    public class ZZDiagnosticScratchTests
    {
        private readonly ITestOutputHelper _out;
        public ZZDiagnosticScratchTests(ITestOutputHelper output) => _out = output;

        [Fact]
        public void Diagnose_MockPipeline()
        {
            var cal = StereoCalibrationData.CreateDefaults(0.4953);
            _out.WriteLine($"cal size: {cal.ImageWidth}x{cal.ImageHeight}");

            var rectifier = new StereoRectifier();
            rectifier.Build(cal);

            using var mock = new MockCameraManager();
            mock.Initialize("soccer");
            mock.StartCapture();

            var registry = new SportProfileRegistry();
            var profile = registry.GetOrDefault("soccer");
            var detector = new BallDetector();
            detector.SetProfile(profile);

            int frames = 0, foundCount = 0;
            for (int i = 0; i < 60; i++)
            {
                if (!mock.FrameQueue.TryTake(out var frame, millisecondsTimeout: 500)) break;
                frames++;

                int rawBright = 0;
                foreach (var b in frame.Data) if (b > 0) rawBright++;

                using var raw = new Mat(frame.Height, frame.Width, DepthType.Cv8U, 1);
                raw.SetTo(frame.Data);
                using var rectified = rectifier.Rectify(raw, frame.CameraIndex);

                var rectBytes = new byte[rectified.Rows * rectified.Cols];
                using (var m = new Matrix<byte>(rectified.Rows, rectified.Cols))
                {
                    rectified.CopyTo(m.Mat);
                    for (int r = 0; r < rectified.Rows; r++)
                        for (int c = 0; c < rectified.Cols; c++)
                            rectBytes[r * rectified.Cols + c] = m[r, c];
                }
                int rectBright = 0;
                foreach (var b in rectBytes) if (b > 0) rectBright++;

                var rectFrame = new CameraFrame
                {
                    CameraIndex = frame.CameraIndex, Data = rectBytes,
                    Width = rectified.Cols, Height = rectified.Rows,
                    TimestampUs = frame.TimestampUs
                };
                var det = detector.Detect(rectFrame);
                if (det.Found) foundCount++;

                if (i < 15 || det.Found)
                {
                    _out.WriteLine($"frame {i} cam={frame.CameraIndex} rawWH={frame.Width}x{frame.Height} " +
                        $"rawBright={rawBright} rectWH={rectified.Cols}x{rectified.Rows} rectBright={rectBright} " +
                        $"found={det.Found} center={det.Center} r={det.RadiusPx} conf={det.Confidence}");
                }
            }

            _out.WriteLine($"TOTAL frames={frames} found={foundCount}");
        }
    }
}

