2	// Vision/Spin3DEstimator.cs
3	// ------------------------------------------------------------
4	// Orchestrates full 3D spin measurement: FeaturePointTracker (natural-
5	// texture detection + optical-flow tracking + stereo matching) feeds
6	// RotationFitter (Kabsch rigid-rotation fit) to recover both spin
7	// MAGNITUDE and AXIS — unlike SpinEstimator's single-camera 2D correlation,
8	// which can only see the rotation component about that one camera's own
9	// viewing axis (blind to backspin/topspin from this rig's overhead angle —
10	// see SpinEstimator.cs and RotationFitter.cs comments).
11	//
12	// AxisUnit is returned in the SAME coordinate frame as Triangulator's
13	// output (camera-relative), NOT yet rotated into shot-relative backspin/
14	// sidespin/spiral terms. That labeling is a follow-on step using the rig's
15	// known mounting tilt (~16.15° — see App/SimulatorEngine.cs) once this
16	// magnitude+axis estimate has been validated against real footage.
17	//
18	// Kabsch only needs points to correspond by identity across two instants —
19	// it centers each point set on its own centroid internally, so the ball's
20	// own translation (flight path) doesn't need to be subtracted separately.
21	//
22	// Natural-texture tracking — reliability against real ball surfaces under
23	// real lighting is UNVALIDATED. See FeaturePointTracker.cs.
24	// ------------------------------------------------------------
25	using System.Collections.Generic;
26	using System.Drawing;
27	using Emgu.CV;
28	using SportSimulator.Tracking;
29	
30	namespace SportSimulator.Vision
31	{
32	    public class Spin3DMeasurement
33	    {
34	        public bool Valid { get; set; }
35	        public float Rpm { get; set; }
36	        public Vec3 AxisUnit { get; set; }  // camera-relative — see class comment
37	        public int PointsUsed { get; set; } // matched-point count the fit used — rough confidence signal
38	    }
39	
40	    public class Spin3DEstimator
41	    {
42	        // Mirrors RotationFitter's own minimum — no point calling Fit() below this.
43	        private const int MinMatchedPoints = 3;
44	
45	        // Same staleness guard as SpinEstimator.cs: a gap this large (dropped
46	        // frame, coast period, camera switch) isn't a "near-consecutive" pair.
47	        private const float MaxDtSeconds = 0.05f;
48	
49	        private readonly FeaturePointTracker _tracker = new();
50	        private readonly Triangulator _triangulator;
51	
52	        private Dictionary<int, Vec3>? _prevById;
53	        private long _prevTimestampUs;
54	
55	        public Spin3DEstimator(Triangulator triangulator) => _triangulator = triangulator;
56	
57	        /// <summary>
58	        /// Call once per stereo frame pair where both cameras detected the ball.
59	        /// leftFrame/rightFrame must already be rectified (see
60	        /// App/SimulatorEngine.cs RectifyFrame — the rectifier's undistort+
61	        /// rectify maps are what make row-constrained stereo matching valid).
62	        ///
63	        /// expectedDisparityPx should come from the ball's own just-triangulated
64	        /// position this same frame (TriangulatedPoint.Disparity from the primary
65	        /// Triangulator.TriangulateStereo call in SimulatorEngine.ProcessLoop) —
66	        /// feature points sit near the ball's surface, so their disparity is close
67	        /// to the ball center's. See FeaturePointTracker.FindStereoMatch for why
68	        /// this matters (this rig's disparity varies ~170–870px across a shot's
69	        /// depth range; a fixed search window can't cover that efficiently).
70	        /// </summary>
71	        public Spin3DMeasurement Update(Mat leftFrame, Mat rightFrame, PointF ballCenterLeft,
72	                                         float ballRadiusPx, float expectedDisparityPx, long timestampUs)
73	        {
74	            var tracked = _tracker.Update(leftFrame, ballCenterLeft, ballRadiusPx);
75	
76	            var currById = new Dictionary<int, Vec3>();
77	            foreach (var pt in tracked)
78	            {
79	                var rightMatch = _tracker.FindStereoMatch(leftFrame, pt.Left, rightFrame, expectedDisparityPx);
80	                if (rightMatch == null) continue;
81	
82	                var tri = _triangulator.TriangulateStereo(pt.Left, rightMatch.Value);
83	                if (tri.Tier == TriangulationTier.Monocular) continue; // stereo match rejected internally too
84	
85	                currById[pt.Id] = new Vec3(tri.X, tri.Y, tri.Z);
86	            }
87	
88	            var result = (_prevById == null)
89	                ? new Spin3DMeasurement { Valid = false }
90	                : Estimate(_prevById, currById, (timestampUs - _prevTimestampUs) / 1_000_000f);
91	
92	            _prevById = currById;
93	            _prevTimestampUs = timestampUs;
94	            return result;
95	        }
96	
97	        public void Reset()
98	        {
99	            _tracker.Reset();
100	            _prevById = null;
101	        }
102	
103	        private static Spin3DMeasurement Estimate(Dictionary<int, Vec3> prev, Dictionary<int, Vec3> curr, float dt)
104	        {
105	            if (dt <= 0f || dt > MaxDtSeconds) return new Spin3DMeasurement { Valid = false };
106	
107	            var setA = new List<Vec3>();
108	            var setB = new List<Vec3>();
109	            foreach (var kvp in prev)
110	            {
111	                if (curr.TryGetValue(kvp.Key, out var pCurr))
112	                {
113	                    setA.Add(kvp.Value);
114	                    setB.Add(pCurr);
115	                }
116	            }
117	
118	            if (setA.Count < MinMatchedPoints) return new Spin3DMeasurement { Valid = false };
119	
120	            var fit = RotationFitter.Fit(setA.ToArray(), setB.ToArray());
121	            if (!fit.Valid) return new Spin3DMeasurement { Valid = false };
122	
123	            return new Spin3DMeasurement
124	            {
125	                Valid      = true,
126	                Rpm        = fit.AngleDeg / dt / 6f, // deg/s ÷ 6 = rpm, same formula as SpinEstimator
127	                AxisUnit   = fit.AxisUnit,
128	                PointsUsed = setA.Count
129	            };
130	        }
131	    }
132	}
