1	// ------------------------------------------------------------
2	// Vision/FeaturePointTracker.cs
3	// ------------------------------------------------------------
4	// Detects and tracks distinctive natural-texture points on the ball's
5	// surface (panel seams, laces, stitching) across consecutive frames of the
6	// LEFT camera, and finds each point's stereo correspondence in the RIGHT
7	// (rectified) camera at the same instant. Combined with Triangulator, this
8	// gives each tracked point's 3D position over time, which RotationFitter
9	// turns into full 3D spin (axis + magnitude) — unlike SpinEstimator's
10	// single-camera 2D correlation, which can only see rotation about that one
11	// camera's own viewing axis.
12	//
13	// Natural-texture tracking, not marked/painted balls — reliability depends
14	// entirely on how much contrast the ball's real surface has at 720×540
15	// under real lighting. Untested against real footage; validate before
16	// trusting the numbers, especially for lower-contrast surfaces (a football's
17	// laces/seams are a weaker signal than a soccer ball's panel edges).
18	// ------------------------------------------------------------
19	using System;
20	using System.Collections.Generic;
21	using System.Drawing;
22	using Emgu.CV;
23	using Emgu.CV.CvEnum;
24	using Emgu.CV.Features2D;
25	using Emgu.CV.Structure;
26	
27	namespace SportSimulator.Vision
28	{
29	    public class TrackedPoint
30	    {
31	        public int Id { get; set; }     // persists across frames for the SAME physical feature
32	        public PointF Left { get; set; } // position in the left (rectified) frame
33	    }
34	
35	    public class FeaturePointTracker
36	    {
37	        private const int MaxFeatures     = 20;
38	        private const double QualityLevel = 0.05; // relative to the strongest corner found in the masked region
39	        private const double MinDistancePx = 4;
40	        private const int WinSize          = 11;  // Lucas-Kanade search window
41	        private const int MaxPyramidLevel  = 2;
42	        private const int MinPointsBeforeRedetect = 4;
43	
44	        private readonly GFTTDetector _detector = new(MaxFeatures, QualityLevel, MinDistancePx);
45	
46	        private Mat?     _prevLeftFrame;
47	        private PointF[]? _prevPoints;
48	        private int[]?    _prevIds;
49	        private int       _nextId;
50	
51	        /// <summary>
52	        /// Detect (first call, or whenever tracking has degraded) or continue
53	        /// tracking feature points on the ball in the left camera's rectified
54	        /// frame, restricted to the region around the detected ball.
55	        /// </summary>
56	        public TrackedPoint[] Update(Mat leftFrame, PointF ballCenter, float ballRadiusPx)
57	        {
58	            PointF[] points;
59	            int[] ids;
60	
61	            if (_prevPoints != null && _prevLeftFrame != null && _prevPoints.Length >= MinPointsBeforeRedetect)
62	            {
63	                TrackForward(leftFrame, ballCenter, ballRadiusPx, out points, out ids);
64	                if (points.Length < MinPointsBeforeRedetect)
65	                    DetectFresh(leftFrame, ballCenter, ballRadiusPx, out points, out ids);
66	            }
67	            else
68	            {
69	                DetectFresh(leftFrame, ballCenter, ballRadiusPx, out points, out ids);
70	            }
71	
72	            _prevLeftFrame?.Dispose();
73	            _prevLeftFrame = leftFrame.Clone();
74	            _prevPoints = points;
75	            _prevIds    = ids;
76	
77	            var result = new TrackedPoint[points.Length];
78	            for (int i = 0; i < points.Length; i++)
79	                result[i] = new TrackedPoint { Id = ids[i], Left = points[i] };
80	            return result;
81	        }
82	
83	        public void Reset()
84	        {
85	            _prevLeftFrame?.Dispose();
86	            _prevLeftFrame = null;
87	            _prevPoints = null;
88	            _prevIds = null;
89	        }
90	
91	        // Pyramidal Lucas-Kanade optical flow — this is what preserves point
92	        // IDENTITY frame-to-frame. A fresh detection every frame would give an
93	        // unrelated set of points each time, useless for measuring how any one
94	        // point moved (which is what RotationFitter needs).
95	        private void TrackForward(Mat leftFrame, PointF ballCenter, float ballRadiusPx,
96	                                   out PointF[] points, out int[] ids)
97	        {
98	            CvInvoke.CalcOpticalFlowPyrLK(
99	                _prevLeftFrame!, leftFrame, _prevPoints!,
100	                new Size(WinSize, WinSize), MaxPyramidLevel,
101	                new MCvTermCriteria(20, 0.03),
102	                out var nextPoints, out var status, out _,
103	                LKFlowFlag.Default, 1e-4);
104	
105	            var keptPoints = new List<PointF>();
106	            var keptIds = new List<int>();
107	            float maxDriftSq = (ballRadiusPx * 2f) * (ballRadiusPx * 2f);
108	
109	            for (int i = 0; i < status.Length; i++)
110	            {
111	                if (status[i] == 0) continue; // lost track
112	
113	                // A point that wandered off the ball entirely is a bad track, not
114	                // a real feature to keep — discard rather than let it corrupt the
115	                // rotation fit.
116	                float dx = nextPoints[i].X - ballCenter.X, dy = nextPoints[i].Y - ballCenter.Y;
117	                if (dx * dx + dy * dy > maxDriftSq) continue;
118	
119	                keptPoints.Add(nextPoints[i]);
120	                keptIds.Add(_prevIds![i]);
121	            }
122	
123	            points = keptPoints.ToArray();
124	            ids    = keptIds.ToArray();
125	        }
126	
127	        private void DetectFresh(Mat leftFrame, PointF ballCenter, float ballRadiusPx,
128	                                  out PointF[] points, out int[] ids)
129	        {
130	            using var mask = new Mat(leftFrame.Rows, leftFrame.Cols, DepthType.Cv8U, 1);
131	            mask.SetTo(new MCvScalar(0));
132	            int r = (int)MathF.Ceiling(ballRadiusPx * 1.3f);
133	            CvInvoke.Circle(mask, Point.Round(ballCenter), r, new MCvScalar(255), -1);
134	
135	            var keypoints = _detector.Detect(leftFrame, mask);
136	
137	            points = new PointF[keypoints.Length];
138	            ids    = new int[keypoints.Length];
139	            for (int i = 0; i < keypoints.Length; i++)
140	            {
141	                points[i] = keypoints[i].Point;
142	                ids[i]    = _nextId++;
143	            }
144	        }
145	
146	        // ── Stereo correspondence ────────────────────────────────────────────────
147	
