1	// ------------------------------------------------------------
2	// Tracking/KalmanBallTracker.cs
3	// ------------------------------------------------------------
4	// Simple 6-state Kalman: [x, y, z, vx, vy, vz]
5	//
6	// Emgu.CV 4.9 matrix-writing notes:
7	//   Marshal.Copy to Mat.DataPointer does NOT reliably update KalmanFilter's
8	//   internal matrices — the native KalmanFilter struct may hold its own
9	//   pointers that differ from the managed Mat wrapper's DataPointer.
10	//
11	//   Reliable approaches:
12	//     • Diagonal matrices  → CvInvoke.SetIdentity(mat, scalar)
13	//     • Arbitrary matrices → build a Matrix<float> (has [r,c] indexer),
14	//                            then call matrix.Mat.CopyTo(target)
15	//     • Reading state      → copy to a Matrix<float> and read [r,c]
16	// ------------------------------------------------------------
17	using System;
18	using Emgu.CV;
19	using Emgu.CV.CvEnum;
20	using Emgu.CV.Structure;
21	using SportSimulator.Models;
22	
23	namespace SportSimulator.Tracking
24	{
25	    public class KalmanBallTracker
26	    {
27	        private KalmanFilter? _kf;
28	        private bool _initialized;
29	
30	        public void Configure(SportProfile profile)
31	        {
32	            _kf = new KalmanFilter(6, 3, 0, DepthType.Cv32F);
33	            float q = profile.ProcessNoise;
34	            float r = profile.MeasurementNoise;
35	
36	            // Confirmed on-site 2026-07-22: SpinView reports 199.76fps at default
37	            // (full-frame) settings — reduced-ROI fps is still unmeasured, so this
38	            // is the safe (lower-bound) assumption until that's checked.
39	            float dt = 1f / 199.76f;
40	
41	            SetMatrix(_kf.TransitionMatrix, new float[,]
42	            {
43	                {1,0,0,dt,0,0},
44	                {0,1,0,0,dt,0},
45	                {0,0,1,0,0,dt},
46	                {0,0,0,1,0,0},
47	                {0,0,0,0,1,0},
48	                {0,0,0,0,0,1}
49	            });
50	
51	            SetMatrix(_kf.MeasurementMatrix, new float[,]
52	            {
53	                {1,0,0,0,0,0},
54	                {0,1,0,0,0,0},
55	                {0,0,1,0,0,0}
56	            });
57	
58	            // CvInvoke.SetIdentity is the reliable way to set diagonal Mats
59	            CvInvoke.SetIdentity(_kf.ProcessNoiseCov,     new MCvScalar(q));
60	            CvInvoke.SetIdentity(_kf.MeasurementNoiseCov, new MCvScalar(r));
61	            CvInvoke.SetIdentity(_kf.ErrorCovPost,        new MCvScalar(1.0));
62	
63	            _initialized = false;
64	        }
65	
66	        public (float x, float y, float z, float vx, float vy, float vz) Update(
67	            float mx, float my, float mz)
68	        {
69	            if (_kf == null) return (mx, my, mz, 0, 0, 0);
70	
71	            if (!_initialized)
72	            {
73	                using var init = new Matrix<float>(6, 1);
74	                init[0, 0] = mx; init[1, 0] = my; init[2, 0] = mz;
75	                // vx, vy, vz stay at 0 (Matrix zeroed on construction)
76	                init.Mat.CopyTo(_kf.StatePost);
77	                _initialized = true;
78	            }
79	
80	            _kf.Predict();
81	
82	            using var meas = new Matrix<float>(3, 1);
