        CvInvoke.SetIdentity(_kf.ProcessNoiseCov,     new MCvScalar(q));
        CvInvoke.SetIdentity(_kf.MeasurementNoiseCov, new MCvScalar(r));
        CvInvoke.SetIdentity(_kf.ErrorCovPost,        new MCvScalar(1.0));

        _initialized = false;
    }

