1	// ------------------------------------------------------------
2	// Tracking/KalmanBallTracker.cs
3	// ------------------------------------------------------------
4	// Simple 6-state Kalman: [x, y, z, vx, vy, vz]
5	//
6	// Emgu.CV 4.9 matrix-writing notes:
7	//   Marshal.Copy to Mat.DataPointer does NOT reliably update KalmanFilter's
8	//   internal matrices — the native KalmanFilter struct may hold its own
9	//   pointers that differ from the managed Mat wrapper's DataPointer.
10	//
11	//   Reliable approaches:
12	//     • Diagonal matrices  → CvInvoke.SetIdentity(mat, scalar)
13	//     • Arbitrary matrices → build a Matrix<float> (has [r,c] indexer),
14	//                            then call matrix.Mat.CopyTo(target)
15	//     • Reading state      → copy to a Matrix<float> and read [r,c]
16	// ------------------------------------------------------------
17	using System;
18	using Emgu.CV;
19	using Emgu.CV.CvEnum;
20	using Emgu.CV.Structure;
21	using SportSimulator.Models;
22	
23	namespace SportSimulator.Tracking
24	{
25	    public class KalmanBallTracker
26	    {
27	        private KalmanFilter? _kf;
28	        private bool _initialized;
29	        private long _lastTimestampUs;
30	
31	        // Fallback dt for the very first Update/Predict call, when there's no prior
32	        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
33	        // reports 199.76fps at default (full-frame) settings.
34	        private const float DefaultDt = 1f / 199.76f;
35	
36	        // Guards against a degenerate transition matrix: MinDt covers duplicate/
37	        // non-monotonic timestamps (would otherwise give dt<=0), MaxDt caps a single
38	        // huge gap (e.g. a long coast) from producing an absurd position jump — real
39	        // coast-frame limits (SportProfile.KalmanCoastFrames) bound this in practice.
40	        private const float MinDt = 1e-4f;
41	        private const float MaxDt = 0.5f;
42	
43	        public void Configure(SportProfile profile)
44	        {
45	            _kf = new KalmanFilter(6, 3, 0, DepthType.Cv32F);
46	            float q = profile.ProcessNoise;
