[Fact]
public void ConstantVelocityTrajectory_PositionTracksAndVelocityConvergesEarly()
{
    // KalmanBallTracker seeds its initial velocity from the position delta
    // between the first two measurements (see its class comment) rather than
    // starting at zero — a real capture window doesn't give a fast-moving
    // ball hundreds of frames to "learn" its own speed from scratch. So for a
    // truly constant-velocity trajectory, velocity should already be close to
    // true almost immediately, and stay close — not slowly climb over time.
    var tracker = MakeTracker();
    float dt = 1f / 120f;
    float vxTrue = 10f;

    for (int i = 0; i < 10; i++)
        tracker.Update(i * dt * vxTrue, 0f, 5f, (long)(i * dt * 1_000_000f));
    var (_, _, _, vxEarly, _, _) = tracker.LastState;

    for (int i = 10; i < 60; i++)
        tracker.Update(i * dt * vxTrue, 0f, 5f, (long)(i * dt * 1_000_000f));

    var (px, _, _, vxLate, _, _) = tracker.LastState;
    float expectedX = 59 * dt * vxTrue;

    px.Should().BeApproximately(expectedX, 0.25f,
        "position estimate should be within 25cm of measured position");
    vxEarly.Should().BeApproximately(vxTrue, 0.1f,
        "two-point seeding should recover the true velocity almost immediately, not after many frames");
    vxLate.Should().BeApproximately(vxTrue, 0.1f,
        "velocity estimate should stay close to true — a perfectly constant-velocity trajectory has nothing left to converge on");
}

