36	        // sensitive: two nearby noisy position measurements divided by a small dt
37	        // amplifies detection noise into a wildly inaccurate velocity — the shorter
38	        // the gap, the smaller the true signal relative to the fixed noise floor).
39	        // Averaging N independent noisy measurements via least squares cuts that
40	        // noise's effect by roughly sqrt(N) while still converging in a handful of
41	        // frames rather than hundreds.
42	        private const int SeedSampleCount = 8;
43	        private readonly List<(float mx, float my, float mz, long ts)> _seedBuffer = new();
44	
45	        // Fallback dt for the very first Update/Predict call, when there's no prior
46	        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
47	        // reports 199.76fps at default (full-frame) settings.
48	        private const float DefaultDt = 1f / 199.76f;
