50	        // Guards against a degenerate transition matrix: MinDt covers duplicate/
51	        // non-monotonic timestamps (would otherwise give dt<=0), MaxDt caps a single
52	        // huge gap (e.g. a long coast) from producing an absurd position jump — real
53	        // coast-frame limits (SportProfile.KalmanCoastFrames) bound this in practice.
54	        private const float MinDt = 1e-4f;
55	        private const float MaxDt = 0.5f;
