122	        /// <summary>Predict-only step (Tier 4 coasting). See Update's comment on timestampUs.</summary>
123	        public (float x, float y, float z, float vx, float vy, float vz) Predict(long timestampUs)
124	        {
125	            if (_kf == null || !_initialized) return LastState;
126	            SetTransitionMatrix(RealDt(timestampUs));
