176	        // Ordinary least squares for y = intercept + slope*t.
177	        private static (float intercept, float slope) FitLine(float[] t, float[] y)
178	        {
179	            int n = t.Length;
180	            float sumT = 0, sumY = 0, sumTT = 0, sumTY = 0;
181	            for (int i = 0; i < n; i++)
182	            {
183	                sumT += t[i]; sumY += y[i];
184	                sumTT += t[i] * t[i]; sumTY += t[i] * y[i];
185	            }
186	            float denom = n * sumTT - sumT * sumT;
187	            float slope = denom != 0f ? (n * sumTY - sumT * sumY) / denom : 0f;
188	            float intercept = (sumY - slope * sumT) / n;
189	            return (intercept, slope);
190	        }
