using System;
using System.Collections.Generic;
using Emgu.CV;
using Emgu.CV.CvEnum;
using Emgu.CV.Structure;
using SportSimulator.Models;

namespace SportSimulator.Tracking
{
    public class KalmanBallTracker
    {
        private KalmanFilter? _kf;
        private bool _initialized;
        private long _lastTimestampUs;

        // Buffers the first several real measurements so the filter's initial
        // velocity can be seeded from a least-squares line fit through them,
