        // see git history) or from a raw two-point delta (tried first, but noise-
        // sensitive: two nearby noisy position measurements divided by a small dt
        // amplifies detection noise into a wildly inaccurate velocity — the shorter
        // the gap, the smaller the true signal relative to the fixed noise floor).
        // Averaging N independent noisy measurements via least squares cuts that
        // noise's effect by roughly sqrt(N) while still converging in a handful of
        // frames rather than hundreds.
        private const int SeedSampleCount = 8;
        private readonly List<(float mx, float my, float mz, long ts)> _seedBuffer = new();

        // Fallback dt for the very first Update/Predict call, when there's no prior
        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
        // reports 199.76fps at default (full-frame) settings.
