1	// ------------------------------------------------------------
2	// Vision/MockCameraManager.cs
3	// ------------------------------------------------------------
4	// Software-only ICameraManager for unit tests.
5	// Generates synthetic stereo frame pairs — two cameras side by side,
6	// each seeing a ball flying along a configurable straight-line trajectory.
7	//
8	// No Spinnaker SDK, no hardware required.
9	//
10	// Usage:
11	//   var mock = new MockCameraManager();
12	//   mock.SetTrajectory(speedMps: 30f, launchAngleDeg: 15f, azimuthDeg: 0f);
13	//   var engine = new SimulatorEngine(mock);
14	// ------------------------------------------------------------
15	using System;
16	using System.Collections.Concurrent;
17	using System.Drawing;
18	using System.Threading;
19	using System.Threading.Tasks;
20	using SportSimulator.Profiles;
21	using SportSimulator.Vision.Calibration;
22	
23	namespace SportSimulator.Vision
24	{
25	    public class MockCameraManager : ICameraManager
26	    {
27	        // ── Camera rig geometry ────────────────────────────────────────────────
28	        // Must match whatever camera model StereoRectifier/Triangulator are
29	        // actually configured with (StereoCalibrationData.CreateDefaults(), in the
30	        // real-camera-absent path SimulatorEngine uses) — referencing its constants
31	        // directly rather than guessing our own, since a silent mismatch here
32	        // doesn't throw, it just makes the rectifier's remap sample from the wrong
33	        // place and wash out real disparity almost entirely. See the comment on
34	        // StereoCalibrationData.DefaultFx for the incident this was found in.
35	        private static readonly int   SensorW = StereoCalibrationData.DefaultImageWidth;
36	        private static readonly int   SensorH = StereoCalibrationData.DefaultImageHeight;
37	        private static readonly float FocalPx = (float)StereoCalibrationData.DefaultFx;
38	        private const float  BaselineM      = 0.4953f; // metres between cameras (19.5in)
39	        private const float  CamHeightM     = 0.00f;   // cameras at origin height
40	        // Confirmed on-site 2026-07-22: slant distance from camera to the tee/ball
41	        // spot is ≈3.015m (114in height, 33in forward mounting geometry — see
42	        // notes/14-session-2026-07-22-hardware-bringup.md). Starting the mock ball
43	        // at the old 0.5m default put it deep inside Triangulator's near-field
44	        // self-rejection zone (extreme disparity at close range makes its two
45	        // internal depth methods disagree) for a large chunk of real processing
46	        // time regardless of trajectory speed — see App/Program.cs's trajectory
47	        // comment for the incident this was found investigating.
48	        private const float  BallStartZ     = 2.5f;    // + the 0.5f offset below ≈ 3.0m
49	        private const float  BallStartX     = 0.0f;    // centred left-right
50	
51	        // ── Trajectory ────────────────────────────────────────────────────────
52	        private float _speedMps       = 30f;
53	        private float _launchAngleDeg = 15f;
54	        private float _azimuthDeg     = 0f;
55	
56	        // ── Synthetic noise ───────────────────────────────────────────────────
57	        private float _positionNoisePx = 1.5f;   // pixel std-dev per detection
58	        private readonly Random _rng = new(42);  // seeded for reproducibility
59	
60	        // ── Timing ────────────────────────────────────────────────────────────
61	        // Matches the real rig's confirmed default: SpinView reports 199.76fps
62	        // full-frame (see KalmanBallTracker.cs). Reduced-ROI fps is still unmeasured.
63	        private float _fps = 199.76f;
64	
65	        public BlockingCollection<CameraFrame> FrameQueue { get; } = new(256);
66	
67	        private CancellationTokenSource? _cts;
68	        private string _sportId = "generic";
69	
70	        // Looks up MinContourArea/MaxContourArea for whatever sport is active so the
71	        // synthetic blob actually lands inside BallDetector's accepted range for that
72	        // profile — a fixed radius here previously meant soccer's real 800–8000px²
73	        // window (this blob was ~113px²) never matched, so no mock shot was ever
74	        // detected end-to-end for soccer.
75	        private readonly SportProfileRegistry _profiles = new();
76	        private float _blobRadiusPx = 6f;
77	
78	        // ── Public API ────────────────────────────────────────────────────────
79	
80	        /// <summary>Configure the simulated ball launch.</summary>
81	        public void SetTrajectory(float speedMps = 30f, float launchAngleDeg = 15f,
82	                                  float azimuthDeg = 0f, float fps = 199.76f,
83	                                  float positionNoisePx = 1.5f)
84	        {
85	            _speedMps        = speedMps;
86	            _launchAngleDeg  = launchAngleDeg;
87	            _azimuthDeg      = azimuthDeg;
88	            _fps             = fps;
89	            _positionNoisePx = positionNoisePx;
90	        }
91	
92	        public void Initialize(string activeSportId = "generic") => SetActiveSport(activeSportId);
93	
94	        public void ApplyProfile(string sportId) => SetActiveSport(sportId);
95	
96	        private void SetActiveSport(string sportId)
97	        {
98	            _sportId = sportId;
99	            var p = _profiles.GetOrDefault(sportId);
100	            float midArea = (p.MinContourArea + p.MaxContourArea) / 2f;
101	            _blobRadiusPx = MathF.Sqrt(midArea / MathF.PI);
102	        }
103	
104	        public void StartCapture()
105	        {
106	            _cts = new CancellationTokenSource();
107	            Task.Factory.StartNew(() => GenerateFrames(_cts.Token),
108	                TaskCreationOptions.LongRunning);
109	        }
110	
111	        public void Stop() => _cts?.Cancel();
112	
113	        public void Dispose() { Stop(); FrameQueue.Dispose(); }
114	
115	        // ── Frame generation ──────────────────────────────────────────────────
116	
117	        private void GenerateFrames(CancellationToken ct)
118	        {
119	            float intervalMs = 1000f / _fps;
120	            int   frameCount = (int)(_fps * 2); // 2 seconds of flight
