        private static Spin3DMeasurement Estimate(Dictionary<int, Vec3> prev, Dictionary<int, Vec3> curr, float dt)
        {
            if (dt <= 0f || dt > MaxDtSeconds) return new Spin3DMeasurement { Valid = false };

