22	
23	        // Square grayscale crop centered on the ball, resized to CropSize×CropSize.
24	        // Null if the ball was too close to the frame edge to get a clean crop.
25	        // Consumed by SpinEstimator — NOT used for position/tracking.
26	        public byte[]? Crop { get; set; }
27	        public int CropSize { get; set; }
28	    }
