30	    public class BallDetector
31	    {
32	        private Mat? _background;
33	        private SportProfile _profile = new();
34	
35	        public void SetProfile(SportProfile p) => _profile = p;
36	
37	        public DetectionResult Detect(CameraFrame frame)
38	        {
39	            using var raw = new Mat(frame.Height, frame.Width, DepthType.Cv8U, 1);
40	            raw.SetTo(frame.Data);
41	
42	            // Background subtraction
43	            if (_background == null)
44	            {
45	                _background = raw.Clone();
46	                return new DetectionResult { Found = false };
47	            }
48	
49	            using var diff = new Mat();
50	            CvInvoke.AbsDiff(raw, _background, diff);
51	
52	            // Gaussian blur + threshold
53	            using var blurred = new Mat();
54	            CvInvoke.GaussianBlur(diff, blurred, new Size(5, 5), 1.5);
55	            using var thresh = new Mat();
56	            CvInvoke.Threshold(blurred, thresh, 25, 255, ThresholdType.Binary);
57	
58	            // Morphological cleanup
59	            using var kernel = CvInvoke.GetStructuringElement(ElementShape.Ellipse, new Size(5, 5), new Point(-1, -1));
60	            CvInvoke.MorphologyEx(thresh, thresh, MorphOp.Close, kernel, new Point(-1, -1), 2, BorderType.Default, new MCvScalar());
61	
62	            // Find contours
63	            using var contours = new VectorOfVectorOfPoint();
64	            using var hierarchy = new Mat();
65	            CvInvoke.FindContours(thresh, contours, hierarchy, RetrType.External, ChainApproxMethod.ChainApproxSimple);
66	
67	            DetectionResult best = new() { Found = false, TimestampUs = frame.TimestampUs, CameraIndex = frame.CameraIndex };
68	            float bestScore = 0;
69	
70	            for (int i = 0; i < contours.Size; i++)
71	            {
72	                double area = CvInvoke.ContourArea(contours[i]);
73	                if (area < _profile.MinContourArea || area > _profile.MaxContourArea) continue;
74	
75	                // Image-moment centroid, not the bounding rectangle's center: rect.X
76	                // and rect.Width are integers, so rect.X + rect.Width/2f can only ever
77	                // land on half-pixel increments — it snaps to a coarse grid rather than
78	                // measuring the contour's true center. Moments are area-weighted over
79	                // the actual contour polygon, giving genuine sub-pixel accuracy (~0.1–
80	                // 0.3px on a clean, well-contrasted blob like this one) instead of being
81	                // capped at a 0.5px quantization step. This centroid feeds triangulation,
82	                // the Kalman velocity fit, and Spin3D's point tracking — all three were
83	                // inheriting this same coarse-quantization noise. Falls back to the old
84	                // bounding-rect method only in the degenerate case of a zero-area moment
85	                // (shouldn't happen given the MinContourArea check above already passed).
86	                var moments = CvInvoke.Moments(contours[i], false);
87	                float cx, cy;
88	                if (moments.M00 > 1e-5)
89	                {
90	                    cx = (float)(moments.M10 / moments.M00);
91	                    cy = (float)(moments.M01 / moments.M00);
92	                }
93	                else
94	                {
95	                    var rect = CvInvoke.BoundingRectangle(contours[i]);
96	                    cx = rect.X + rect.Width / 2f;
97	                    cy = rect.Y + rect.Height / 2f;
98	                }
99	                float r = MathF.Sqrt((float)area / MathF.PI);
100	
101	                // Circularity score (1.0 = perfect circle; lower for pucks)
102	                double perim = CvInvoke.ArcLength(contours[i], true);
103	                float circularity = _profile.IsSphere
104	                    ? (float)(4 * Math.PI * area / (perim * perim))
105	                    : 1f; // skip for puck
106	
107	                float score = (float)area * (circularity * 0.5f + 0.5f);
108	                if (score > bestScore)
109	                {
110	                    bestScore = score;
111	                    best = new DetectionResult
112	                    {
113	                        Found = true,
114	                        Center = new PointF(cx, cy),
115	                        RadiusPx = r,
116	                        Confidence = MathF.Max(0f, MathF.Min(1f, circularity)),
117	                        TimestampUs = frame.TimestampUs,
118	                        CameraIndex = frame.CameraIndex
119	                    };
120	                }
121	            }
122	
123	            // Rolling background update
124	            CvInvoke.AddWeighted(_background, 0.95, raw, 0.05, 0, _background);
125	
126	            if (best.Found)
127	            {
128	                best.Crop = ExtractCrop(raw, best.Center, best.RadiusPx, out int cropSize);
129	                best.CropSize = cropSize;
130	            }
131	
132	            return best;
133	        }
134	
135	        // Fixed output size for spin crops. Kept a multiple of 4 so Emgu.CV's
136	        // Cv8U row stride never needs padding — avoids stride bugs when reading
137	        // the Mat back out as a flat byte[].
138	        private const int SpinCropSize = 48;
139	
140	        // Pad around the detected radius, clip to frame bounds, and resize to a
141	        // fixed square so SpinEstimator can compare crops of the same size across
142	        // frames regardless of how big the ball appeared in each one.
143	        private static byte[]? ExtractCrop(Mat raw, PointF center, float radiusPx, out int size)
144	        {
145	            size = SpinCropSize;
146	            int pad = Math.Max(8, (int)MathF.Ceiling(radiusPx * 1.6f));
147	            var wanted = new Rectangle((int)(center.X - pad), (int)(center.Y - pad), pad * 2, pad * 2);
148	            var bounds = new Rectangle(0, 0, raw.Cols, raw.Rows);
149	            var clipped = Rectangle.Intersect(wanted, bounds);
150	
151	            // Ball too close to the frame edge — a lopsided crop puts the ball off
152	            //-center, which throws off the rotation-about-center search in
153	            // SpinEstimator. Require at least 75% of the padded box (pad*2) to
154	            // survive clipping; skip rather than resize a skewed sliver.
155	            // (Note: because a detected center is always inside [0, raw.Cols) /
156	            // [0, raw.Rows), single-edge clipping alone can only ever remove up to
157	            // half the padded box — this threshold is what makes the check reachable.)
158	            if (clipped.Width < pad * 1.5f || clipped.Height < pad * 1.5f) return null;
159	
160	            using var roi = new Mat(raw, clipped);
161	            using var resized = new Mat();
162	            CvInvoke.Resize(roi, resized, new Size(size, size));
163	
164	            // Matrix<byte> with indexer — same reliable read pattern documented in
165	            // KalmanBallTracker.cs / Triangulator.cs for pulling data back out of a Mat.
166	            using var m = new Matrix<byte>(size, size);
167	            resized.CopyTo(m.Mat);
168	            var bytes = new byte[size * size];
169	            for (int r = 0; r < size; r++)
170	                for (int c = 0; c < size; c++)
171	                    bytes[r * size + c] = m[r, c];
172	            return bytes;
173	        }
174	    }
175	}

