16	namespace SportSimulator.App
17	{
18	    public class SimulatorEngine : IDisposable
19	    {
20	        private readonly ICameraManager    _cameras;
21	        private readonly BallDetector      _detector = new();
22	        private readonly KalmanBallTracker _tracker = new();
23	        private readonly SportProfileRegistry _registry = new();
24	        private readonly StereoRectifier _rectifier = new();
25	        private readonly Triangulator    _triangulator = new();
