13	{
14	    public class DetectionResult
15	    {
16	        public bool Found { get; set; }
17	        public PointF Center { get; set; }
18	        public float RadiusPx { get; set; }
19	        public float Confidence { get; set; }
20	        public long TimestampUs { get; set; }
21	        public int CameraIndex { get; set; }
22	
23	        // Square grayscale crop centered on the ball, resized to CropSize×CropSize.
24	        // Null if the ball was too close to the frame edge to get a clean crop.
25	        // Consumed by SpinEstimator — NOT used for position/tracking.
26	        public byte[]? Crop { get; set; }
27	        public int CropSize { get; set; }
28	    }
29	
30	    public class BallDetector
31	    {
32	        private Mat? _background;
33	        private SportProfile _profile = new();
34	
35	        public void SetProfile(SportProfile p) => _profile = p;
36	
37	        public DetectionResult Detect(CameraFrame frame)
38	        {
39	            using var raw = new Mat(frame.Height, frame.Width, DepthType.Cv8U, 1);
40	            raw.SetTo(frame.Data);
41	
42	            // Background subtraction
43	            if (_background == null)
44	            {
45	                _background = raw.Clone();
46	                return new DetectionResult { Found = false };
47	            }
48	
49	            using var diff = new Mat();
50	            CvInvoke.AbsDiff(raw, _background, diff);
51	
52	            // Gaussian blur + threshold
53	            using var blurred = new Mat();
54	            CvInvoke.GaussianBlur(diff, blurred, new Size(5, 5), 1.5);
55	            using var thresh = new Mat();
56	            CvInvoke.Threshold(blurred, thresh, 25, 255, ThresholdType.Binary);
57	
58	            // Morphological cleanup
59	            using var kernel = CvInvoke.GetStructuringElement(ElementShape.Ellipse, new Size(5, 5), new Point(-1, -1));
60	            CvInvoke.MorphologyEx(thresh, thresh, MorphOp.Close, kernel, new Point(-1, -1), 2, BorderType.Default, new MCvScalar());
61	
62	            // Find contours
63	            using var contours = new VectorOfVectorOfPoint();
64	            using var hierarchy = new Mat();
65	            CvInvoke.FindContours(thresh, contours, hierarchy, RetrType.External, ChainApproxMethod.ChainApproxSimple);
66	
67	            DetectionResult best = new() { Found = false, TimestampUs = frame.TimestampUs, CameraIndex = frame.CameraIndex };
68	            float bestScore = 0;
69	
70	            for (int i = 0; i < contours.Size; i++)
71	            {
72	                double area = CvInvoke.ContourArea(contours[i]);
73	                if (area < _profile.MinContourArea || area > _profile.MaxContourArea) continue;
74	
75	                var rect = CvInvoke.BoundingRectangle(contours[i]);
76	                float cx = rect.X + rect.Width / 2f;
77	                float cy = rect.Y + rect.Height / 2f;
78	                float r = MathF.Sqrt((float)area / MathF.PI);
79	
80	                // Circularity score (1.0 = perfect circle; lower for pucks)
81	                double perim = CvInvoke.ArcLength(contours[i], true);
82	                float circularity = _profile.IsSphere
83	                    ? (float)(4 * Math.PI * area / (perim * perim))
84	                    : 1f; // skip for puck
85	
86	                float score = (float)area * (circularity * 0.5f + 0.5f);
87	                if (score > bestScore)
88	                {
89	                    bestScore = score;
90	                    best = new DetectionResult
91	                    {
92	                        Found = true,
93	                        Center = new PointF(cx, cy),
94	                        RadiusPx = r,
95	                        Confidence = MathF.Max(0f, MathF.Min(1f, circularity)),
96	                        TimestampUs = frame.TimestampUs,
97	                        CameraIndex = frame.CameraIndex
98	                    };
99	                }
100	            }
101	
102	            // Rolling background update
103	            CvInvoke.AddWeighted(_background, 0.95, raw, 0.05, 0, _background);
104	
105	            if (best.Found)
106	            {
107	                best.Crop = ExtractCrop(raw, best.Center, best.RadiusPx, out int cropSize);
108	                best.CropSize = cropSize;
109	            }
110	
111	            return best;
112	        }
113	
114	        // Fixed output size for spin crops. Kept a multiple of 4 so Emgu.CV's
115	        // Cv8U row stride never needs padding — avoids stride bugs when reading
116	        // the Mat back out as a flat byte[].
117	        private const int SpinCropSize = 48;
118	
119	        // Pad around the detected radius, clip to frame bounds, and resize to a
120	        // fixed square so SpinEstimator can compare crops of the same size across
121	        // frames regardless of how big the ball appeared in each one.
122	        private static byte[]? ExtractCrop(Mat raw, PointF center, float radiusPx, out int size)
123	        {
124	            size = SpinCropSize;
125	            int pad = Math.Max(8, (int)MathF.Ceiling(radiusPx * 1.6f));
126	            var wanted = new Rectangle((int)(center.X - pad), (int)(center.Y - pad), pad * 2, pad * 2);
127	            var bounds = new Rectangle(0, 0, raw.Cols, raw.Rows);
128	            var clipped = Rectangle.Intersect(wanted, bounds);
129	
130	            // Ball too close to the frame edge — a lopsided crop puts the ball off
131	            //-center, which throws off the rotation-about-center search in
132	            // SpinEstimator. Require at least 75% of the padded box (pad*2) to
133	            // survive clipping; skip rather than resize a skewed sliver.
134	            // (Note: because a detected center is always inside [0, raw.Cols) /
135	            // [0, raw.Rows), single-edge clipping alone can only ever remove up to
136	            // half the padded box — this threshold is what makes the check reachable.)
137	            if (clipped.Width < pad * 1.5f || clipped.Height < pad * 1.5f) return null;
138	
139	            using var roi = new Mat(raw, clipped);
140	            using var resized = new Mat();
141	            CvInvoke.Resize(roi, resized, new Size(size, size));
142	
143	            // Matrix<byte> with indexer — same reliable read pattern documented in
144	            // KalmanBallTracker.cs / Triangulator.cs for pulling data back out of a Mat.
145	            using var m = new Matrix<byte>(size, size);
146	            resized.CopyTo(m.Mat);
147	            var bytes = new byte[size * size];
148	            for (int r = 0; r < size; r++)
149	                for (int c = 0; c < size; c++)
150	                    bytes[r * size + c] = m[r, c];
151	            return bytes;
152	        }
153	    }
