28	
29	        /// <summary>
30	        /// Production constructor — uses the real Spinnaker-backed CameraManager.
31	        /// Only available on net48 (Spinnaker SDK is not present on net10.0).
32	        /// </summary>
33	#if NET48
34	        public SimulatorEngine() : this(new CameraManager()) { }
35	#endif
36	
37	        /// <summary>
38	        /// Injection constructor — pass a MockCameraManager (or any ICameraManager)
39	        /// for unit tests on machines without the Spinnaker SDK.
40	        /// </summary>
41	        public SimulatorEngine(ICameraManager cameras)
42	        {
43	            _cameras = cameras;
44	            _activeProfile = _registry.GetOrDefault("soccer");
45	            _spin3DEstimator = new Spin3DEstimator(_triangulator);
46	            _skipSpinEstimation = cameras is MockCameraManager;
47	        }
48	
49	        // MockCameraManager's ball has no real rotating surface texture — both
50	        // SpinEstimator (2D correlation) and Spin3DEstimator (natural-texture point
51	        // tracking) need one to produce a genuine signal. Without it, the recovered
52	        // axis is essentially random from frame to frame (confirmed live: readings
53	        // stayed under the plausibility cap yet still visibly perturbed the ball's
54	        // path in Unity — BallController overwrites its Magnus-force spin vector on
55	        // every packet, so a rapidly rotating random axis reads as a jittery,
56	        // "squiggly" path even though it nets out close to straight). Capping
57	        // magnitude only stops the worst outliers; it can't fix an axis that has no
58	        // real information in it. Skip spin estimation entirely for mock testing —
59	        // real spin validation needs a real textured ball on real hardware, same as
60	        // this code's comments have said from the start.
61	        private readonly bool _skipSpinEstimation;
62	
63	        private UdpTransport? _udp;
64	        private SportProfile  _activeProfile = null!; // set in constructor before use
65	        private bool _running;
66	
67	        // Latest detection from each camera, keyed by camera index
68	        private readonly Dictionary<int, DetectionResult> _pending = new();
69	        private readonly object _pendingLock = new();
70	
71	        // Max frames the Kalman filter will predict forward without any detection.
72	        // Set from SportProfile.KalmanCoastFrames on each profile switch.
73	        private int _maxCoastFrames = 5;
74	        private int _coastFrames = 0;
75	
76	        // Triangulator.TriangulateMonocular computes X/Y from a single camera's pixel
77	        // position PLUS the tracker's own last-known Z — not an independent Z
78	        // measurement. That Z then gets fed straight back into the Kalman filter via
79	        // Update(), so during a sustained run of monocular-only cycles (common once
80	        // real stereo agreement gets shaky further from the camera), nothing ever
81	        // independently confirms Z — the filter just echoes back whatever it already
82	        // believed. Any small error in the Z-velocity estimate never gets corrected
83	        // and compounds unbounded the longer the streak runs. Found live: a faster
84	        // (25 m/s) mock shot spent longer in this state per real-time interval and
85	        // the final result diverged to a nonsensical (10.6, 6.6, 55.4) position —
86	        // an 18 m/s shot showed the same declining-confidence pattern, just not
87	        // severely enough to visibly diverge within its shorter tracked window.
88	        // Capping how many CONSECUTIVE non-independent fixes get fed to Update()
89	        // before falling back to Predict()-only coasting bounds how far this can
90	        // drift, matching (but distinct from) the existing _coastFrames idea for
91	        // genuine "no detection at all" cycles.
92	        private const int MaxConsecutiveMonocular = 15;
93	        private int _consecutiveMonocularTicks = 0;
94	
95	        // Most recent ball crop seen per camera, for frame-to-frame spin correlation.
96	        // Keyed by CameraIndex. See SpinEstimator.cs for method + current limits
97	        // (reliable for soccer's spin rates at 120fps; not yet for golf/baseball/tennis).
98	        private readonly Dictionary<int, (byte[] crop, int size, long timestampUs)> _lastCrop = new();
99	        private float _lastSpinRpm = 0f;
100	
101	        // Full 3D spin (magnitude + axis) via natural-texture point tracking —
102	        // see Vision/Spin3DEstimator.cs. Only runs when both cameras detected the
103	        // ball this cycle (needs a stereo pair for triangulation). Takes priority
104	        // over the single-camera 2D SpinEstimator above when it produces a valid
105	        // fit; the 2D estimate remains as a magnitude-only fallback otherwise
106	        // (e.g. too few tracked/matched points this cycle).
107	        // AxisUnit is camera-relative, NOT yet rotated into shot-relative
108	        // backspin/sidespin terms — see Spin3DEstimator.cs class comment.
109	        private Vec3 _lastSpinAxis = default;
110	        private int  _logFrameCounter = 0;
111	
112	        // Holds the most recently computed BallData from a REAL (non-KalmanOnly)
113	        // measurement — i.e. the Kalman filter's fused estimate as of the latest
114	        // actual detection, not a coasted/extrapolated one. Overwritten every real
115	        // cycle, so it always reflects the best available consolidated result.
116	        // Actually sent to Unity only once, when the shot ends (see the Tier 4
117	        // coast-timeout branch) — see notes/11-unity-integration.md: the original
118	        // design called for one "shot result" message per ball, not a continuous
119	        // stream. The previous per-cycle Send() sent hundreds of packets per shot
120	        // (each overwriting BallController's velocity in Unity), which worked once
121	        // the underlying tracking was fixed, but doesn't match either the intended
122	        // design or how real launch monitors report a shot.
123	        private BallData? _pendingShotData;
124	
125	        // Calibration file path — generated by running StereoCalibrator once.
126	        // ⚠️ SETUP TODO — run the calibration routine before first real use:
127	        //   1. Print a 9×6 checkerboard with 25mm squares
128	        //   2. Hold it at various positions/angles visible to both cameras
129	        //   3. Call StereoCalibrator.AddFramePair() for 15+ positions
130	        //   4. Call StereoCalibrator.Calibrate() — outputs this JSON file
131	        //   5. Aim for RMS reprojection error < 1.0px (< 0.5px is excellent)
132	        // Until this file exists, CreateDefaults() is used as a fallback.
133	        private const string CalibPath = "stereo_calibration.json";
134	
135	        public void Start(string unityIp = "127.0.0.1", int sendPort = 7100, int listenPort = 7101)
136	        {
137	            LoadCalibration();
138	
139	            _udp = new UdpTransport(unityIp, sendPort, listenPort);
140	            _udp.ProfileCommandReceived += OnProfileCommand;
141	            _udp.StartListening();
142	
143	            _cameras.Initialize(_activeProfile.SportId);
144	            ApplyProfile(_activeProfile);
145	            _cameras.StartCapture();
146	
147	            _running = true;
148	            Console.WriteLine("[Engine] Running. Waiting for stereo frame pairs...");
149	            ProcessLoop();
150	        }
151	
152	        private void LoadCalibration()
153	        {
154	            StereoCalibrationData cal;
155	            if (System.IO.File.Exists(CalibPath))
156	            {
157	                cal = StereoCalibrationData.LoadFromFile(CalibPath);
158	                Console.WriteLine($"[Engine] Loaded calibration from {CalibPath}");
159	            }
160	            else
161	            {
162	                // ⚠️ SETUP TODO — using estimated defaults until calibration is run.
163	                // Baseline measured at 19.5in center-to-center → 19.5 * 0.0254 = 0.4953m.
164	                // Sensor resolution/focal length below are still unconfirmed placeholders —
165	                // update once the checkerboard calibration (StereoCalibrator) has been run.
166	                cal = StereoCalibrationData.CreateDefaults(baselineMetres: 0.4953);
167	                Console.WriteLine("[Engine] WARNING: Using default calibration. Run StereoCalibrator for accuracy.");
168	            }
169	
170	            _rectifier.Build(cal);
171	            _triangulator.Configure(cal);
172	        }
173	
174	        private void OnProfileCommand(ProfileSelectCommand cmd)
175	        {
176	            // Unity's ProfileSelectSender resends the same sport a few times on
177	            // startup in case the middleware isn't listening yet (no ack in this
178	            // protocol — see Assets/Scripts/ProfileSelectSender.cs). Re-applying an
179	            // already-active profile is a no-op in terms of configuration, but
180	            // ApplyProfile rebuilds the Kalman tracker from scratch — if one of
181	            // those redundant resends lands while a shot is actually mid-flight
182	            // (the mock test window overlaps it easily), it silently wipes the
183	            // tracker's converged velocity back to zero. Skip the reset entirely
184	            // when nothing is actually changing.
185	            if (string.Equals(cmd.SportId, _activeProfile.SportId, StringComparison.OrdinalIgnoreCase))
186	                return;
187	
188	            var p = _registry.GetOrDefault(cmd.SportId);
189	            ApplyProfile(p);
190	            Console.WriteLine($"[Engine] Profile switched to: {p.DisplayName}");
191	        }
192	
193	        private void ApplyProfile(SportProfile p)
194	        {
195	            _activeProfile  = p;
196	            _detector.SetProfile(p);
197	            _tracker.Configure(p);
198	            _cameras.ApplyProfile(p.SportId);
199	            _maxCoastFrames = p.KalmanCoastFrames;
200	            Console.WriteLine($"[Engine] Coast window set to {_maxCoastFrames} frames for {p.DisplayName}");
201	        }
202	
203	        private void ProcessLoop()
204	        {
205	            while (_running)
206	            {
207	                // Drain all frames that arrived since last iteration
208	                DetectionResult? det0 = null, det1 = null;
209	                CameraFrame? rectFrame0 = null, rectFrame1 = null;
210	
211	                while (_cameras.FrameQueue.TryTake(out var frame, 5))
212	                {
213	                    // Detection, triangulation (disparity + DLT via P0/P1), and
214	                    // stereo point-matching for 3D spin all assume RECTIFIED image
215	                    // coordinates — undistorted, with corresponding points on the
216	                    // same row between cameras. Rectify before anything else touches
217	                    // the frame.
218	                    var rectified = RectifyFrame(frame);
219	                    var det = _detector.Detect(rectified);
220	                    if (!det.Found) continue;
221	                    if (!_skipSpinEstimation) UpdateSpinEstimate(det);
222	                    if (det.CameraIndex == 0) { det0 = det; rectFrame0 = rectified; }
223	                    else                      { det1 = det; rectFrame1 = rectified; }
224	                }
225	
226	                TriangulatedPoint? pt3d = null;
227	
228	                // ── Tier 1 / 2: both cameras this cycle ─────────────────────────
229	                if (det0 != null && det1 != null)
230	                {
231	                    pt3d = _triangulator.TriangulateStereo(det0.Center, det1.Center);
232	
233	                    // If stereo disagreed and fell to monocular internally, enrich it
234	                    // with the Kalman's last Z — but only once a real stereo fix has
235	                    // already established a genuine Z. Before that, LastState.z is
236	                    // itself a meaningless 0, so "enriching" with it just produces
237	                    // ANOTHER degenerate (0,0,0) point — found by seeing every single
238	                    // one of a Kalman seed's buffered measurements come back at exactly
239	                    // (0.000, 0.000, 0.000): this self-referential loop, not real data,
240	                    // was what the seed was actually being built from. Same root cause
241	                    // as the Tier 3 fix below, just a different code path into it.
242	                    if (pt3d.Tier == TriangulationTier.Monocular && pt3d.Z == 0)
243	                    {
244	                        if (!_tracker.HasFix)
245	                        {
246	                            _coastFrames++;
247	                            if (_coastFrames > _maxCoastFrames) continue;
248	                            pt3d = new TriangulatedPoint
249	                            {
250	                                X = 0, Y = 0, Z = 0,
251	                                Confidence = 0.05f,
252	                                Tier = TriangulationTier.KalmanOnly,
253	                                TierReason = "Stereo self-rejected, no prior fix yet to enrich from"
254	                            };
255	                        }
256	                        else if (_consecutiveMonocularTicks >= MaxConsecutiveMonocular)
257	                        {
258	                            // Stop trusting the self-referential Z — coast on the
259	                            // filter's own prediction instead of feeding it another
260	                            // "confirmation" of a value it already produced itself.
261	                            var (kx, ky, kz, _, _, _) = _tracker.LastState;
262	                            pt3d = new TriangulatedPoint
263	                            {
264	                                X = kx, Y = ky, Z = kz,
265	                                Confidence = 0.1f,
266	                                Tier = TriangulationTier.KalmanOnly,
267	                                TierReason = $"Too many consecutive monocular fixes ({_consecutiveMonocularTicks}), coasting instead"
268	                            };
269	                        }
270	                        else
271	                        {
272	                            var (kx, ky, kz, _, _, _) = _tracker.LastState;
273	                            pt3d = _triangulator.TriangulateMonocular(det0.Center, kz);
274	                            _consecutiveMonocularTicks++;
275	                        }
276	                    }
277	                    else
278	                    {
279	                        // Genuine independent stereo fix — Z was actually confirmed
280	                        // this cycle, not echoed back from the filter's own belief.
281	                        _consecutiveMonocularTicks = 0;
282	                    }
283	
284	                    if (pt3d.Tier != TriangulationTier.KalmanOnly)
285	                    {
286	                        if (!_skipSpinEstimation) UpdateSpin3D(rectFrame0!, rectFrame1!, det0, pt3d);
287	                        _coastFrames = 0;
288	                    }
289	                }
290	                // ── Tier 3: only one camera this cycle ──────────────────────────
291	                else if (det0 != null || det1 != null)
292	                {
293	                    // TriangulateMonocular needs an existing depth reference (the
294	                    // tracker's own last Z) — before any real stereo (Tier 1/2) fix
295	                    // has ever landed, that's a meaningless 0, and treating it as
296	                    // real would hand the tracker a fabricated point. That point
297	                    // would then poison KalmanBallTracker's two-point velocity seed
298	                    // (see its class comment) once a genuine stereo fix follows.
299	                    // Coast instead until stereo actually establishes a real Z.
300	                    if (!_tracker.HasFix)
301	                    {
302	                        _coastFrames++;
303	                        if (_coastFrames > _maxCoastFrames) continue;
304	                        pt3d = new TriangulatedPoint
305	                        {
306	                            X = 0, Y = 0, Z = 0,
307	                            Confidence = 0.05f,
308	                            Tier = TriangulationTier.KalmanOnly,
309	                            TierReason = "Single camera, no stereo fix yet to anchor depth"
310	                        };
311	                    }
312	                    else if (_consecutiveMonocularTicks >= MaxConsecutiveMonocular)
313	                    {
314	                        var (kx, ky, kz, _, _, _) = _tracker.LastState;
315	                        pt3d = new TriangulatedPoint
316	                        {
317	                            X = kx, Y = ky, Z = kz,
318	                            Confidence = 0.1f,
319	                            Tier = TriangulationTier.KalmanOnly,
320	                            TierReason = $"Too many consecutive monocular fixes ({_consecutiveMonocularTicks}), coasting instead"
321	                        };
322	                    }
323	                    else
324	                    {
325	                        var single = (det0 ?? det1)!;
326	                        var (_, _, kz, _, _, _) = _tracker.LastState;
327	                        pt3d = _triangulator.TriangulateMonocular(single.Center, kz);
328	                        _consecutiveMonocularTicks++;
329	                        _coastFrames = 0;
330	                    }
331	                }
332	                // ── Tier 4: no detection — Kalman coast ─────────────────────────
333	                else
334	                {
335	                    _coastFrames++;
336	                    if (_coastFrames > _maxCoastFrames)
337	                    {
338	                        // Ball genuinely gone — this is the one point where a shot
339	                        // actually ends. Send whatever the last real measurement
340	                        // produced (if any shot was in progress) and reset for the
341	                        // next one.
342	                        SendPendingShotAndReset();
343	                        continue;
344	                    }
345	
346	                    var (kx, ky, kz, _, _, _) = _tracker.LastState;
347	                    float coastConf = Math.Max(0.05f, 0.3f - _coastFrames * (0.25f / _maxCoastFrames));
348	                    pt3d = new TriangulatedPoint
349	                    {
350	                        X = kx, Y = ky, Z = kz,
351	                        Confidence = coastConf,
352	                        Tier       = TriangulationTier.KalmanOnly,
353	                        TierReason = $"Coasting frame {_coastFrames}/{_maxCoastFrames}"
354	                    };
355	                }
356	
357	                // Flip Y: OpenCV Y-down → Unity Y-up
358	                float mx = pt3d.X, my = -pt3d.Y, mz = pt3d.Z;
359	
360	                // Real frame-capture timestamp when we have one — NOT wall-clock time
361	                // of this call — so KalmanBallTracker can compute its own real elapsed
362	                // dt regardless of how many frames got batched into this cycle. Falls
363	                // back to wall-clock only for a pure coast cycle (no detection at all
364	                // this cycle, so no frame timestamp exists) — see KalmanBallTracker.
365	                long ts = det0?.TimestampUs ?? det1?.TimestampUs
366	                    ?? DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() * 1000;
367	
368	                // Only feed real measurements into Kalman; coast uses predict-only
369	                (float x, float y, float z, float vx, float vy, float vz) state;
370	                if (pt3d.Tier == TriangulationTier.KalmanOnly)
371	                    state = _tracker.Predict(ts);
372	                else
373	                    state = _tracker.Update(mx, my, mz, ts);
374	
375	                var (sx, sy, sz, svx, svy, svz) = state;
376	                float speed       = MathF.Sqrt(svx*svx + svy*svy + svz*svz);
377	                float launchAngle = _activeProfile.OutputLaunchAngle
378	                    ? MathF.Atan2(svy, MathF.Sqrt(svx*svx + svz*svz)) * 180f / MathF.PI
379	                    : 0f;
380	
381	                // Average detection confidence with triangulation confidence
382	                float detConf = det0 != null && det1 != null
383	                    ? (det0.Confidence + det1.Confidence) * 0.5f
384	                    : (det0?.Confidence ?? det1?.Confidence ?? 0f);
385	                float finalConf = (detConf + pt3d.Confidence) * 0.5f;
386	
387	                var ballData = new BallData
388	                {
389	                    SportId        = _activeProfile.SportId,
390	                    TimestampUs    = ts,
391	                    PosX = sx, PosY = sy, PosZ = sz,
392	                    VelX = svx, VelY = svy, VelZ = svz,
393	                    SpeedMps       = speed,
394	                    LaunchAngleDeg = launchAngle,
395	                    SpinRpm        = _activeProfile.OutputSpin ? _lastSpinRpm : 0f,
396	                    SpinAxisX      = _activeProfile.OutputSpin ? _lastSpinAxis.X : 0f,
397	                    SpinAxisY      = _activeProfile.OutputSpin ? _lastSpinAxis.Y : 0f,
398	                    SpinAxisZ      = _activeProfile.OutputSpin ? _lastSpinAxis.Z : 0f,
399	                    Confidence     = finalConf,
400	                    TrackingTier   = (int)pt3d.Tier
401	                };
402	
403	                // Cache rather than send — only once the tracker has actually
404	                // converged (HasFix) does svx/svy/svz mean anything; before that,
405	                // "real" tiers still report a placeholder zero velocity while
406	                // gathering the seed buffer (see KalmanBallTracker.Update), so
407	                // caching on tier alone caught that and sent a spurious speed=0
408	                // "shot" if a brief early coast-timeout hit before seeding finished.
409	                // Actually sent once, when the shot ends (Tier 4 coast-timeout
410	                // branch above / SendPendingShotAndReset below).
411	                if (pt3d.Tier != TriangulationTier.KalmanOnly && _tracker.HasFix)
412	                    _pendingShotData = ballData;
413	
414	                // Throttled live-tracking readout — diagnostic only, not a send
415	                // indicator. At ~200fps, logging every frame would be an unreadable
416	                // firehose; every 20th frame is still a live ~10Hz readout while
417	                // testing, without flooding the console.
418	                if (++_logFrameCounter % 20 == 0)
419	                {
420	                    Console.WriteLine(
421	                        $"[Tracking] pos=({sx:F2},{sy:F2},{sz:F2}) speed={speed:F1}m/s tier={pt3d.Tier} " +
422	                        $"conf={finalConf:F2} spin={_lastSpinRpm:F0}rpm axis=({_lastSpinAxis.X:F2},{_lastSpinAxis.Y:F2},{_lastSpinAxis.Z:F2})");
423	                }
424	            }
425	        }
426	
427	        // Called once the ball has genuinely left trackable range (coast frames
428	        // exceeded). Sends the last real measurement's consolidated result — the
429	        // Kalman filter's fused estimate as of the final detection, incorporating
430	        // every real measurement across the whole visible flight — as a single
431	        // packet, then resets tracking state for the next shot. A no-op if no shot
432	        // was ever established (e.g. still waiting for the first ball).
433	        private void SendPendingShotAndReset()
434	        {
435	            if (_pendingShotData == null) return;
436	
437	            _udp?.Send(_pendingShotData);
438	            Console.WriteLine(
439	                $"[Shot] Sent final result: pos=({_pendingShotData.PosX:F2},{_pendingShotData.PosY:F2},{_pendingShotData.PosZ:F2}) " +
440	                $"speed={_pendingShotData.SpeedMps:F1}m/s spin={_pendingShotData.SpinRpm:F0}rpm " +
441	                $"conf={_pendingShotData.Confidence:F2}");
442	
443	            _pendingShotData = null;
444	            _tracker.Configure(_activeProfile);
445	            _coastFrames = 0;
446	            _consecutiveMonocularTicks = 0;
447	            _lastSpinRpm = 0f;
448	            _lastSpinAxis = default;
449	        }
450	
451	        // Apply the stereo undistort+rectify maps (built once in LoadCalibration)
452	        // to a raw captured frame.
453	        private CameraFrame RectifyFrame(CameraFrame frame)
454	        {
455	            using var raw = new Mat(frame.Height, frame.Width, DepthType.Cv8U, 1);
456	            raw.SetTo(frame.Data);
457	            using var rectified = _rectifier.Rectify(raw, frame.CameraIndex);
458	
459	            // Bulk CopyTo, not a per-pixel Matrix<byte> indexer loop (that pattern is
460	            // fine for BallDetector.ExtractCrop's tiny 48×48 spin crop, but doing it
461	            // over a full 720×540 frame — 388,800 individual marshalled indexer calls,
462	            // per camera, per frame — took ~14ms measured, well over the ~5ms budget
463	            // at 200fps. That backlogged the frame queue faster than it could drain,
464	            // collapsing an entire shot into one stale batch by the time processing
465	            // caught up. CopyTo(byte[]) does the same read in one native call.
466	            var bytes = new byte[rectified.Rows * rectified.Cols];
467	            rectified.CopyTo(bytes);
468	
469	            return new CameraFrame
470	            {
471	                CameraIndex    = frame.CameraIndex,
472	                Data           = bytes,
473	                Width          = rectified.Cols,
474	                Height         = rectified.Rows,
475	                TimestampUs    = frame.TimestampUs,
476	                ExposureTimeUs = frame.ExposureTimeUs,
477	                GainDb         = frame.GainDb
478	            };
479	        }
480	
481	        // Full 3D spin (magnitude + axis) — only possible when both cameras
482	        // detected the ball this cycle, since it needs a stereo pair to
483	        // triangulate tracked feature points. Falls through silently (leaving
484	        // _lastSpinRpm/_lastSpinAxis at their previous values) when the fit isn't
485	        // valid this frame — UpdateSpinEstimate's single-camera 2D magnitude-only
486	        // fallback keeps running independently either way.
487	        private void UpdateSpin3D(CameraFrame leftFrame, CameraFrame rightFrame, DetectionResult det0, TriangulatedPoint pt3d)
488	        {
489	            if (!_activeProfile.OutputSpin) return;
490	
491	            using var leftMat  = FrameToMat(leftFrame);
492	            using var rightMat = FrameToMat(rightFrame);
493	
494	            var m = _spin3DEstimator.Update(leftMat, rightMat, det0.Center, det0.RadiusPx,
495	                                             pt3d.Disparity, leftFrame.TimestampUs);
496	            if (!m.Valid) return;
497	
498	            _lastSpinRpm  = m.Rpm;
499	            _lastSpinAxis = m.AxisUnit;
500	
501	            // Unthrottled, unlike the general trajectory log below — how OFTEN this
502	            // line appears at all is itself the key diagnostic for whether natural-
503	            // texture tracking is finding enough points on your real ball surfaces
504	            // (see Vision/FeaturePointTracker.cs). Axis is camera-relative, not yet
505	            // rotated into backspin/sidespin terms — see Vision/Spin3DEstimator.cs.
506	            Console.WriteLine($"[Spin3D] rpm={m.Rpm:F0} axis=({m.AxisUnit.X:F2},{m.AxisUnit.Y:F2},{m.AxisUnit.Z:F2}) points={m.PointsUsed}");
507	        }
508	
509	        private static Mat FrameToMat(CameraFrame frame)
510	        {
511	            var m = new Mat(frame.Height, frame.Width, DepthType.Cv8U, 1);
512	            m.SetTo(frame.Data);
513	            return m;
514	        }
515	
516	        // Correlate this detection's crop against the last one seen from the SAME
517	        // camera to estimate rotation. Pairs more than 50ms apart (dropped frame,
518	        // coast gap, camera switch) are skipped rather than fed to the estimator —
519	        // the rotation-search range assumes near-consecutive frames.
520	        private void UpdateSpinEstimate(DetectionResult det)
521	        {
522	            if (!_activeProfile.OutputSpin || det.Crop == null) return;
523	
524	            if (_lastCrop.TryGetValue(det.CameraIndex, out var prev) && prev.size == det.CropSize)
525	            {
526	                float dt = (det.TimestampUs - prev.timestampUs) / 1_000_000f;
527	                if (dt > 0f && dt < 0.05f)
528	                {
529	                    var m = _spinEstimator.Estimate(prev.crop, det.Crop, det.CropSize, dt);
530	                    if (m.Valid) _lastSpinRpm = m.Rpm;
531	                }
532	            }
533	
534	            _lastCrop[det.CameraIndex] = (det.Crop, det.CropSize, det.TimestampUs);
535	        }
536	
537	        public void Stop() => _running = false;
538	        public void Dispose() { Stop(); _cameras.Dispose(); _udp?.Dispose(); }
539	    }
540	}

