1	// ------------------------------------------------------------
2	// Vision/MockCameraManager.cs
3	// ------------------------------------------------------------
4	// Software-only ICameraManager for unit tests.
5	// Generates synthetic stereo frame pairs — two cameras side by side,
6	// each seeing a ball flying along a configurable straight-line trajectory.
7	//
8	// No Spinnaker SDK, no hardware required.
9	//
10	// Usage:
11	//   var mock = new MockCameraManager();
12	//   mock.SetTrajectory(speedMps: 30f, launchAngleDeg: 15f, azimuthDeg: 0f);
13	//   var engine = new SimulatorEngine(mock);
14	// ------------------------------------------------------------
15	using System;
16	using System.Collections.Concurrent;
17	using System.Drawing;
18	using System.Threading;
19	using System.Threading.Tasks;
20	using SportSimulator.Profiles;
21	using SportSimulator.Vision.Calibration;
22	
23	namespace SportSimulator.Vision
24	{
25	    public class MockCameraManager : ICameraManager
26	    {
27	        // ── Camera rig geometry ────────────────────────────────────────────────
28	        // Must match whatever camera model StereoRectifier/Triangulator are
29	        // actually configured with (StereoCalibrationData.CreateDefaults(), in the
30	        // real-camera-absent path SimulatorEngine uses) — referencing its constants
31	        // directly rather than guessing our own, since a silent mismatch here
32	        // doesn't throw, it just makes the rectifier's remap sample from the wrong
33	        // place and wash out real disparity almost entirely. See the comment on
34	        // StereoCalibrationData.DefaultFx for the incident this was found in.
35	        private static readonly int   SensorW = StereoCalibrationData.DefaultImageWidth;
36	        private static readonly int   SensorH = StereoCalibrationData.DefaultImageHeight;
37	        private static readonly float FocalPx = (float)StereoCalibrationData.DefaultFx;
38	        private const float  BaselineM      = 0.4953f; // metres between cameras (19.5in)
39	        private const float  CamHeightM     = 0.00f;   // cameras at origin height
40	        // Confirmed on-site 2026-07-22: slant distance from camera to the tee/ball
41	        // spot is ≈3.015m (114in height, 33in forward mounting geometry — see
42	        // notes/14-session-2026-07-22-hardware-bringup.md). Starting the mock ball
43	        // at the old 0.5m default put it deep inside Triangulator's near-field
44	        // self-rejection zone (extreme disparity at close range makes its two
45	        // internal depth methods disagree) for a large chunk of real processing
46	        // time regardless of trajectory speed — see App/Program.cs's trajectory
47	        // comment for the incident this was found investigating.
48	        private const float  BallStartZ     = 2.5f;    // + the 0.5f offset below ≈ 3.0m
49	        private const float  BallStartX     = 0.0f;    // centred left-right
50	
51	        // ── Trajectory ────────────────────────────────────────────────────────
52	        private float _speedMps       = 30f;
53	        private float _launchAngleDeg = 15f;
54	        private float _azimuthDeg     = 0f;
55	
56	        // ── Synthetic noise ───────────────────────────────────────────────────
57	        // Was 1.5px, calibrated to the old BallDetector's bounding-rect-center method
58	        // (integer-quantized to 0.5px steps, plus real quantization/threshold jitter).
59	        // BallDetector now computes a moment-based sub-pixel centroid instead — real
60	        // achievable accuracy on a clean, well-contrasted blob this size is ~0.1–0.3px,
61	        // not 1.5px. Injecting noise sized for a detector this rig no longer runs
62	        // overstates real depth/velocity uncertainty: at Z=5m, 1.5px of disparity noise
63	        // implies ~6cm of depth error per measurement — comparable to or larger than
64	        // the ball's actual per-frame displacement, which was swamping the Kalman
65	        // velocity fit with noise levels that will never actually occur.
66	        private float _positionNoisePx = 0.3f;   // pixel std-dev per detection
67	        private readonly Random _rng = new(42);  // seeded for reproducibility
68	
69	        // Fixed relative offsets (fractions of the ball's radius) for a handful of
70	        // interior speckles, generated once and drawn unrotated on every frame.
71	        // Without these, the ball was a perfectly flat white disc — FeaturePointTracker's
72	        // GFTT corner detector had no real interior texture to lock onto, so it tracked
73	        // edge/threshold noise instead, producing wildly different "rotation" readings
74	        // frame to frame (single-digit rpm one moment, ~1000rpm the next, random axis
75	        // each time). BallController applies that spin as a real Magnus force — one
76	        // such spurious high-rpm reading with a near-vertical axis was enough to send
77	        // the ball into a visible circular orbit in Unity instead of a straight,
78	        // decaying flight. Keeping the pattern's orientation fixed (never rotating it)
79	        // matches the physical truth: this mock doesn't model ball spin at all, so the
80	        // correct answer for Spin3D to recover here is ~0rpm, not noise.
81	        private readonly (float dx, float dy)[] _speckleOffsets;
82	
83	        // ── Timing ────────────────────────────────────────────────────────────
84	        // Matches the real rig's confirmed default: SpinView reports 199.76fps
85	        // full-frame (see KalmanBallTracker.cs). Reduced-ROI fps is still unmeasured.
86	        private float _fps = 199.76f;
87	
88	        public BlockingCollection<CameraFrame> FrameQueue { get; } = new(256);
89	
90	        private CancellationTokenSource? _cts;
91	        private string _sportId = "generic";
92	
93	        // Looks up MinContourArea/MaxContourArea for whatever sport is active so the
94	        // synthetic blob actually lands inside BallDetector's accepted range for that
95	        // profile — a fixed radius here previously meant soccer's real 800–8000px²
96	        // window (this blob was ~113px²) never matched, so no mock shot was ever
97	        // detected end-to-end for soccer.
98	        private readonly SportProfileRegistry _profiles = new();
99	        private float _blobRadiusPx = 6f;
100	
101	        public MockCameraManager()
102	        {
103	            const int speckleCount = 10;
104	            _speckleOffsets = new (float, float)[speckleCount];
105	            for (int i = 0; i < speckleCount; i++)
106	            {
107	                float angle  = (float)(_rng.NextDouble() * 2.0 * Math.PI);
108	                float radius = 0.25f + (float)_rng.NextDouble() * 0.5f; // 0.25–0.75 of ball radius
109	                _speckleOffsets[i] = (MathF.Cos(angle) * radius, MathF.Sin(angle) * radius);
110	            }
111	        }
112	
113	        // ── Public API ────────────────────────────────────────────────────────
114	
115	        /// <summary>Configure the simulated ball launch.</summary>
116	        public void SetTrajectory(float speedMps = 30f, float launchAngleDeg = 15f,
117	                                  float azimuthDeg = 0f, float fps = 199.76f,
118	                                  float positionNoisePx = 0.3f)
119	        {
120	            _speedMps        = speedMps;
121	            _launchAngleDeg  = launchAngleDeg;
122	            _azimuthDeg      = azimuthDeg;
123	            _fps             = fps;
124	            _positionNoisePx = positionNoisePx;
125	        }
126	
127	        public void Initialize(string activeSportId = "generic") => SetActiveSport(activeSportId);
128	
129	        public void ApplyProfile(string sportId) => SetActiveSport(sportId);
130	
131	        private void SetActiveSport(string sportId)
132	        {
133	            _sportId = sportId;
134	            var p = _profiles.GetOrDefault(sportId);
135	            float midArea = (p.MinContourArea + p.MaxContourArea) / 2f;
136	            _blobRadiusPx = MathF.Sqrt(midArea / MathF.PI);
137	        }
138	
139	        public void StartCapture()
140	        {
141	            _cts = new CancellationTokenSource();
142	            Task.Factory.StartNew(() => GenerateFrames(_cts.Token),
143	                TaskCreationOptions.LongRunning);
144	        }
145	
146	        public void Stop() => _cts?.Cancel();
147	
148	        public void Dispose() { Stop(); FrameQueue.Dispose(); }
149	
150	        // ── Frame generation ──────────────────────────────────────────────────
151	
152	        private void GenerateFrames(CancellationToken ct)
153	        {
154	            float intervalMs = 1000f / _fps;
155	            int   frameCount = (int)(_fps * 2); // 2 seconds of flight
156	
157	            // Decompose velocity into world components
158	            float launchRad  = _launchAngleDeg * MathF.PI / 180f;
159	            float azimuthRad = _azimuthDeg      * MathF.PI / 180f;
160	            float vz = _speedMps * MathF.Cos(launchRad) * MathF.Cos(azimuthRad);
161	            float vx = _speedMps * MathF.Cos(launchRad) * MathF.Sin(azimuthRad);
162	            float vy = _speedMps * MathF.Sin(launchRad);
163	
164	            float dt    = 1f / _fps;
165	            float bx    = BallStartX;
166	            float by    = CamHeightM;
167	            float bz    = BallStartZ + 0.5f; // start 0.5m in front of cameras
168	
169	            long  timestampUs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() * 1000L;
170	
171	            for (int f = 0; f < frameCount && !ct.IsCancellationRequested; f++)
172	            {
173	                // Advance ball position (gravity on Y)
174	                bx += vx * dt;
175	                by += vy * dt - 0.5f * 9.81f * dt * dt;
176	                bz += vz * dt;
177	                vy -= 9.81f * dt;
178	
179	                // Project onto each camera sensor
180	                // Camera 0: at (-baseline/2, 0, 0)  looking +Z
181	                // Camera 1: at (+baseline/2, 0, 0)  looking +Z
182	                var frame0 = ProjectToCamera(bx + BaselineM / 2f, by, bz, 0, timestampUs);
183	                var frame1 = ProjectToCamera(bx - BaselineM / 2f, by, bz, 1, timestampUs);
184	
185	                if (frame0 != null) FrameQueue.TryAdd(frame0);
186	                if (frame1 != null) FrameQueue.TryAdd(frame1);
187	
188	                timestampUs += (long)(dt * 1_000_000f);
189	                Thread.Sleep((int)intervalMs);
190	            }
191	        }
192	
193	        private CameraFrame? ProjectToCamera(float relX, float relY, float relZ,
194	                                              int camIdx, long timestampUs)
195	        {
196	            if (relZ <= 0f) return null; // behind camera
197	
198	            // Perspective projection
199	            float px = FocalPx * relX / relZ + SensorW / 2f;
200	            float py = FocalPx * (-relY) / relZ + SensorH / 2f; // Y-down
201	
202	            // Add Gaussian noise
203	            px += (float)SampleGaussian() * _positionNoisePx;
204	            py += (float)SampleGaussian() * _positionNoisePx;
205	
206	            if (px < 0 || px >= SensorW || py < 0 || py >= SensorH) return null; // off-sensor
207	
208	            // Build a minimal synthetic frame: black background, white ball blob.
209	            // Radius is sized (in SetActiveSport) to land inside the active profile's
210	            // MinContourArea/MaxContourArea band — not a physically-projected size,
211	            // just enough to make BallDetector actually fire for whichever sport is
212	            // selected. Clamped so a custom/generic profile with an extreme area
213	            // range can't produce a degenerate (near-zero or off-sensor) blob.
214	            int   r      = Math.Max(2, Math.Min(200, (int)MathF.Round(_blobRadiusPx)));
215	            var   data   = new byte[SensorW * SensorH];
216	            int   cx     = (int)px;
217	            int   cy     = (int)py;
218	
219	            for (int dy = -r; dy <= r; dy++)
220	            for (int dx = -r; dx <= r; dx++)
221	            {
222	                if (dx*dx + dy*dy > r*r) continue;
223	                int row = cy + dy, col = cx + dx;
224	                if (row < 0 || row >= SensorH || col < 0 || col >= SensorW) continue;
225	                data[row * SensorW + col] = 255;
226	            }
227	
228	            // Interior speckles for FeaturePointTracker to actually track — see the
229	            // class comment on _speckleOffsets. Offsets are fractions of r, so they
230	            // scale correctly with whatever sport profile sized the blob.
231	            const int speckleDotRadius = 2;
232	            const byte speckleValue = 90; // dark enough against the 255 fill for GFTT/stdDev checks
233	            foreach (var (odx, ody) in _speckleOffsets)
234	            {
235	                int scx = cx + (int)MathF.Round(odx * r);
236	                int scy = cy + (int)MathF.Round(ody * r);
237	                for (int dy = -speckleDotRadius; dy <= speckleDotRadius; dy++)
238	                for (int dx = -speckleDotRadius; dx <= speckleDotRadius; dx++)
239	                {
240	                    if (dx*dx + dy*dy > speckleDotRadius*speckleDotRadius) continue;
241	                    int row = scy + dy, col = scx + dx;
242	                    if (row < 0 || row >= SensorH || col < 0 || col >= SensorW) continue;
243	                    data[row * SensorW + col] = speckleValue;
244	                }
245	            }
246	
247	            return new CameraFrame
248	            {
249	                CameraIndex    = camIdx,
250	                Data           = data,
251	                Width          = SensorW,
252	                Height         = SensorH,
253	                TimestampUs    = timestampUs,
254	                ExposureTimeUs = 500.0,
255	                GainDb         = 0.0
256	            };
257	        }
258	
259	        // Box-Muller transform for Gaussian noise
260	        private double SampleGaussian()
261	        {
262	            double u1 = 1.0 - _rng.NextDouble();
263	            double u2 = 1.0 - _rng.NextDouble();
264	            return Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
265	        }
266	    }
267	}
