1	// ------------------------------------------------------------
2	// Tracking/KalmanBallTracker.cs
3	// ------------------------------------------------------------
4	// Simple 6-state Kalman: [x, y, z, vx, vy, vz]
5	//
6	// Emgu.CV 4.9 matrix-writing notes:
7	//   Marshal.Copy to Mat.DataPointer does NOT reliably update KalmanFilter's
8	//   internal matrices — the native KalmanFilter struct may hold its own
9	//   pointers that differ from the managed Mat wrapper's DataPointer.
10	//
11	//   Reliable approaches:
12	//     • Diagonal matrices  → CvInvoke.SetIdentity(mat, scalar)
13	//     • Arbitrary matrices → build a Matrix<float> (has [r,c] indexer),
14	//                            then call matrix.Mat.CopyTo(target)
15	//     • Reading state      → copy to a Matrix<float> and read [r,c]
16	// ------------------------------------------------------------
17	using System;
18	using System.Collections.Generic;
19	using Emgu.CV;
20	using Emgu.CV.CvEnum;
21	using Emgu.CV.Structure;
22	using SportSimulator.Models;
23	
24	namespace SportSimulator.Tracking
25	{
26	    public class KalmanBallTracker
27	    {
28	        private KalmanFilter? _kf;
29	        private bool _initialized;
30	        private long _lastTimestampUs;
31	
32	        // Buffers the first several real measurements so the filter's initial
33	        // velocity can be seeded from a least-squares line fit through them,
34	        // instead of starting at zero (too slow to "learn" the ball is moving —
35	        // see git history) or from a raw two-point delta (tried first, but noise-
36	        // sensitive: two nearby noisy position measurements divided by a small dt
37	        // amplifies detection noise into a wildly inaccurate velocity — the shorter
38	        // the gap, the smaller the true signal relative to the fixed noise floor).
39	        // Averaging N independent noisy measurements via least squares cuts that
40	        // noise's effect by roughly sqrt(N) while still converging in a handful of
41	        // frames rather than hundreds.
42	        private const int SeedSampleCount = 8;
43	        private readonly List<(float mx, float my, float mz, long ts)> _seedBuffer = new();
44	
45	        // Fallback dt for the very first Update/Predict call, when there's no prior
46	        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
47	        // reports 199.76fps at default (full-frame) settings.
48	        private const float DefaultDt = 1f / 199.76f;
49	
50	        // Guards against a degenerate transition matrix: MinDt covers duplicate/
51	        // non-monotonic timestamps (would otherwise give dt<=0), MaxDt caps a single
52	        // huge gap (e.g. a long coast) from producing an absurd position jump — real
53	        // coast-frame limits (SportProfile.KalmanCoastFrames) bound this in practice.
54	        private const float MinDt = 1e-4f;
55	        private const float MaxDt = 0.5f;
56	
57	        public void Configure(SportProfile profile)
58	        {
59	            _kf = new KalmanFilter(6, 3, 0, DepthType.Cv32F);
60	            float q = profile.ProcessNoise;
61	            float r = profile.MeasurementNoise;
62	
63	            SetTransitionMatrix(DefaultDt);
64	
65	            SetMatrix(_kf.MeasurementMatrix, new float[,]
66	            {
67	                {1,0,0,0,0,0},
68	                {0,1,0,0,0,0},
69	                {0,0,1,0,0,0}
70	            });
71	
72	            // CvInvoke.SetIdentity is the reliable way to set diagonal Mats
73	            CvInvoke.SetIdentity(_kf.ProcessNoiseCov,     new MCvScalar(q));
74	            CvInvoke.SetIdentity(_kf.MeasurementNoiseCov, new MCvScalar(r));
75	            CvInvoke.SetIdentity(_kf.ErrorCovPost,        new MCvScalar(1.0));
76	
77	            _initialized = false;
78	            _seedBuffer.Clear();
79	        }
80	
81	        // Position-only measurement update. timestampUs is the frame's own capture
82	        // timestamp — NOT wall-clock time of when this method happens to be called.
83	        // The transition matrix's dt is rebuilt from the real elapsed time since the
84	        // last call rather than assumed fixed, because callers don't call this once
85	        // per camera tick: SimulatorEngine.ProcessLoop batches a variable number of
86	        // frames per cycle depending on processing load, so a hardcoded dt here
87	        // systematically distorted the recovered velocity — see App/SimulatorEngine.cs
88	        // ProcessLoop and this class's git history for the incident that caught it
89	        // (mock ball moved far too slowly because reported speed was ~10x too low).
90	        public (float x, float y, float z, float vx, float vy, float vz) Update(
91	            float mx, float my, float mz, long timestampUs)
92	        {
93	            if (_kf == null) return (mx, my, mz, 0, 0, 0);
94	
95	            if (!_initialized)
96	            {
97	                _seedBuffer.Add((mx, my, mz, timestampUs));
98	
99	                if (_seedBuffer.Count < SeedSampleCount)
100	                {
101	                    // Still gathering samples — report at face value with zero
102	                    // velocity, same as the old pre-seeding behavior.
103	                    LastState = (mx, my, mz, 0, 0, 0);
104	                    return LastState;
105	                }
106	
107	                SeedFromBuffer();
108	                return LastState;
109	            }
110	
111	            SetTransitionMatrix(RealDt(timestampUs));
112	            _kf.Predict();
113	
114	            using var meas = new Matrix<float>(3, 1);
115	            meas[0, 0] = mx; meas[1, 0] = my; meas[2, 0] = mz;
116	
117	            CacheState(_kf.Correct(meas.Mat));
118	            _lastTimestampUs = timestampUs;
119	            return LastState;
120	        }
121	
122	        /// <summary>Predict-only step (Tier 4 coasting). See Update's comment on timestampUs.</summary>
123	        public (float x, float y, float z, float vx, float vy, float vz) Predict(long timestampUs)
124	        {
125	            if (_kf == null || !_initialized) return LastState;
126	            SetTransitionMatrix(RealDt(timestampUs));
127	            CacheState(_kf.Predict());
128	            _lastTimestampUs = timestampUs;
129	            return LastState;
130	        }
131	
132	        // Fits an independent least-squares line (position vs. time) through the
133	        // buffered samples for each axis, seeds the filter's state directly from
134	        // the fit's velocity (slope) and its position at the last sample's time
135	        // (evaluating the fit there, rather than trusting that one raw noisy
136	        // measurement, smooths noise on the position estimate too) — then commits
137	        // it as the filter's current belief with no extra Predict() step, same
138	        // reasoning as the two-point version this replaced: the fit already
139	        // represents the state AT the last sample's timestamp, so advancing it
140	        // again would overshoot.
141	        private void SeedFromBuffer()
142	        {
143	            int n = _seedBuffer.Count;
144	            var t = new float[n];
145	            var xs = new float[n];
146	            var ys = new float[n];
147	            var zs = new float[n];
148	            long t0 = _seedBuffer[0].ts;
149	            for (int i = 0; i < n; i++)
150	            {
151	                var s = _seedBuffer[i];
152	                t[i]  = (s.ts - t0) / 1_000_000f; // relative seconds — keeps values small for float precision
153	                xs[i] = s.mx; ys[i] = s.my; zs[i] = s.mz;
154	            }
155	
156	            var (x0, vx0) = FitLine(t, xs);
157	            var (y0, vy0) = FitLine(t, ys);
158	            var (z0, vz0) = FitLine(t, zs);
159	            float tLast = t[n - 1];
160	            long lastTimestampUs = _seedBuffer[n - 1].ts;
161	
162	            using var init = new Matrix<float>(6, 1);
163	            init[0, 0] = x0 + vx0 * tLast;
164	            init[1, 0] = y0 + vy0 * tLast;
165	            init[2, 0] = z0 + vz0 * tLast;
166	            init[3, 0] = vx0; init[4, 0] = vy0; init[5, 0] = vz0;
167	            init.Mat.CopyTo(_kf!.StatePost);
168	
169	            SetTransitionMatrix(ClampDt(t[n - 1] - t[n - 2]));
170	            _initialized = true;
171	            _seedBuffer.Clear();
172	            CacheState(_kf.StatePost);
173	            _lastTimestampUs = lastTimestampUs;
174	        }
175	
176	        // Ordinary least squares for y = intercept + slope*t.
177	        private static (float intercept, float slope) FitLine(float[] t, float[] y)
178	        {
179	            int n = t.Length;
180	            float sumT = 0, sumY = 0, sumTT = 0, sumTY = 0;

