using System;
using SportSimulator.App;
using SportSimulator.Vision;

var unityIp   = args.Length > 0 ? args[0] : "127.0.0.1";
var sendPort  = args.Length > 1 ? int.Parse(args[1]) : 7100;
var listenPort = args.Length > 2 ? int.Parse(args[2]) : 7101;

Console.WriteLine("=== SportSimulator ===");
Console.WriteLine($"Unity target : {unityIp}:{sendPort}");
Console.WriteLine($"Listen port  : {listenPort}");
Console.WriteLine("Press Ctrl+C to exit.\n");

#if NET48
using var engine = new SimulatorEngine();          // real Spinnaker cameras
#else
Console.WriteLine("[WARNING] Running without Spinnaker SDK — MockCameraManager active.");
var mock = new MockCameraManager();
// Default (30 m/s, 15°) is a full-power drive-distance kick that flies the ball
// past Triangulator's 10m stereo range within under a second — way beyond the
// real rig's actual working distance (~3m slant to the tee, per notes/14-...md).
// A real shot only needs to be tracked in a brief burst near the tee before Unity
// takes over the flight locally; this trajectory stays within stereo range for
// longer, giving the Kalman filter a realistic number of real measurements to
// converge on before the ball exits useful tracking range.
// Negative azimuth = left side of the net (positive azimuth -> positive world X ->
// positive Unity X -> Unity's GoalkeeperAI treats positive ballX as the right
// side, confirmed via its own "isLeftSide" log output on a straight, azimuth=0
// shot). Spin stays disabled for mock testing (see SimulatorEngine's
// _skipSpinEstimation), so this is a pure, curve-free aim change.
//
// atan((SensorW/2)/fx) ~= 11.6 degrees is the sensor's half-angle measured from
// dead center, but it's not a hard per-axis ceiling: MockCameraManager.
// ProjectToCamera rejects a frame only once its actual projected pixel position
// leaves [0,SensorW)x[0,SensorH) — a ball with both lateral (azimuth) and
// vertical (launch angle) displacement can still be well inside that rectangle
// even past 11.6 degrees on either axis alone, since the two offsets are along
// different pixel axes, not additive along one. Verified empirically once the
// shared-background/ghost-trail detector bugs were fixed: this rig tracks
// combined azimuth + launch angle shots well past 15/14 degrees cleanly through
// their full flight (FullStereo -> Monocular, no drift, single consolidated
// [Shot] result) — the ball leaves stereo range from simply flying far enough
// away (Z growing), not from exiting either camera's frame.
//
// launchAngleDeg bumped 14 -> 17.5: with the Tier 3 fix landed, Unity now gets
// an accurate full-flight velocity instead of one frozen partway through, and
// the 14-degree shot reported back as "almost reached the net before hitting
// the ground" — closer than before this session's fixes, but still landing
// short. 20 degrees was tried first and made things WORSE: this rig's vertical
// half-angle (atan((SensorH/2)/fx) ~= 8.7 degrees) is much tighter than the
// horizontal one, and unlike azimuth's monotonic lateral drift, a steep enough
// vertical launch pushes the ball ABOVE both cameras' frame simultaneously
// (CamHeightM=0, so the same by/bz ratio trips both cameras at once — confirmed
// live: tier read "KalmanOnly" — total loss — not "Monocular", exactly as
// that symmetry predicts). At 20 degrees the ball leaves vertical frame around
// Z=5.6m and doesn't re-enter until Z=12.5m — a gap the 8-frame coast window
// comes nowhere near bridging, so the shot got cut off with only ~2 real ticks
// and an under-converged, LOW speed reading (15.5 m/s instead of the true 18).
// 17.5 degrees stays comfortably clear of that exit threshold for this whole
// trajectory (same margin the working 14-degree shot had), while still roughly
// doubling the ball's height at the goal line versus 14 degrees.
mock.SetTrajectory(speedMps: 15f, launchAngleDeg: 45f, azimuthDeg: 0f);
using var engine = new SimulatorEngine(mock);
#endif

Console.CancelKeyPress += (_, e) => { e.Cancel = true; engine.Stop(); };

engine.Start(unityIp, sendPort, listenPort);

