184	                sumTT += t[i] * t[i]; sumTY += t[i] * y[i];
185	            }
186	            float denom = n * sumTT - sumT * sumT;
187	            float slope = denom != 0f ? (n * sumTY - sumT * sumY) / denom : 0f;
188	            float intercept = (sumY - slope * sumT) / n;
