private KalmanFilter? _kf;
private bool _initialized;
private long _lastTimestampUs;

// Seeding used to buffer several real measurements and least-squares fit a
// line through them (see git history) — needs several independent real
// detections to average noise down. This rig's confirmed camera geometry
// (114in height, ~33in forward, steep downward tilt — see notes/14-...md
// and App/Program.cs) gives a real forward flight-tracking window of only
// ~18 inches at the tee before the ball crosses the bottom of frame —
// confirmed three independent ways this session (tilt-derived geometry,
// a physical tape measurement in SpinView, and the mock's own live
// behavior). At realistic shot speeds that's often only 1-2 real
// detections total, nowhere near enough to average.
//
// Instead: the ball's REST position (address/tee) is a known, calibrated
// point, not something that needs detecting — it's ~zero-noise, unlike a
// second raw camera measurement. Track the last timestamp the ball was
// seen sitting at that known rest position; the instant a real detection
// shows it meaningfully displaced, that's the shot starting, and a single
// two-point delta (known rest position/time -> this one noisy detection)
// gives a velocity estimate with HALF the noise sources of a raw two-point
// delta between two noisy detections, and needs only ONE real detection
// after the ball leaves rest — not several.
//
// If no "at rest" detection ever lands before the first moving one (e.g.
// the ball wasn't visible yet when Configure() was called), falls back to
// treating Configure()'s own call time as t0 — a real hardware impact
// trigger (IR break-beam/mic — see notes/04-hardware-triggering.md) would
// slot in here as a strictly more precise t0 if/when this rig has one;
// nothing else about this design would need to change.
private const float RestPositionToleranceM = 0.03f; // ball radius is a few cm; this must be well under one ball-width of drift
public float RestX { get; private set; }
public float RestY { get; private set; }
public float RestZ { get; private set; }
private long _lastRestTimestampUs;
private bool _haveRestTimestamp;

