// Fits an independent least-squares line (position vs. time) through the
// buffered samples for each axis, seeds the filter's state directly from
// the fit's velocity (slope) and its position at the last sample's time
// (evaluating the fit there, rather than trusting that one raw noisy
// measurement, smooths noise on the position estimate too) — then commits
// it as the filter's current belief with no extra Predict() step, same
// reasoning as the two-point version this replaced: the fit already
// represents the state AT the last sample's timestamp, so advancing it
// again would overshoot.
private void SeedFromBuffer()
{
    int n = _seedBuffer.Count;
    var t = new float[n];
    var xs = new float[n];
    var ys = new float[n];
    var zs = new float[n];
    long t0 = _seedBuffer[0].ts;
    for (int i = 0; i < n; i++)
    {
        var s = _seedBuffer[i];
        t[i]  = (s.ts - t0) / 1_000_000f; // relative seconds — keeps values small for float precision
        xs[i] = s.mx; ys[i] = s.my; zs[i] = s.mz;
    }

    var (x0, vx0) = FitLine(t, xs);
    var (y0, vy0) = FitLine(t, ys);
    var (z0, vz0) = FitLine(t, zs);
    float tLast = t[n - 1];
    long lastTimestampUs = _seedBuffer[n - 1].ts;

    using var init = new Matrix<float>(6, 1);
    init[0, 0] = x0 + vx0 * tLast;
    init[1, 0] = y0 + vy0 * tLast;
    init[2, 0] = z0 + vz0 * tLast;
    init[3, 0] = vx0; init[4, 0] = vy0; init[5, 0] = vz0;
    init.Mat.CopyTo(_kf!.StatePost);

    SetTransitionMatrix(ClampDt(t[n - 1] - t[n - 2]));
    _initialized = true;
    _seedBuffer.Clear();
    CacheState(_kf.StatePost);
    _lastTimestampUs = lastTimestampUs;
}

// Ordinary least squares for y = intercept + slope*t.
private static (float intercept, float slope) FitLine(float[] t, float[] y)
{
    int n = t.Length;
    float sumT = 0, sumY = 0, sumTT = 0, sumTY = 0;
    for (int i = 0; i < n; i++)
    {
        sumT += t[i]; sumY += y[i];
        sumTT += t[i] * t[i]; sumTY += t[i] * y[i];
    }
    float denom = n * sumTT - sumT * sumT;
    float slope = denom != 0f ? (n * sumTY - sumT * sumY) / denom : 0f;
    float intercept = (sumY - slope * sumT) / n;
    return (intercept, slope);
}

