1	// ------------------------------------------------------------
2	// Vision/Triangulator.cs
3	// ------------------------------------------------------------
4	// Given matched 2D detections from left + right rectified cameras,
5	// reconstructs the 3D world point using the Q disparity-to-depth
6	// matrix and OpenCV triangulatePoints.
7	// Wide baseline (500–900mm): good depth resolution at 1–5m range.
8	// ------------------------------------------------------------
9	using System;
10	using System.Drawing;
11	using System.Runtime.InteropServices;
12	using Emgu.CV;
13	using Emgu.CV.CvEnum;
14	using Emgu.CV.Structure;
15	using Emgu.CV.Util;
16	using SportSimulator.Vision.Calibration;
17	
18	namespace SportSimulator.Vision
19	{
20	    public enum TriangulationTier
21	    {
22	        FullStereo   = 1,  // both cams agree well       — high confidence
23	        BlendedStereo = 2, // both cams, moderate disagreement — medium confidence
24	        Monocular    = 3,  // only one cam detected ball  — low confidence
25	        KalmanOnly   = 4   // no detection this frame     — prediction only
26	    }
27	
28	    public class TriangulatedPoint
29	    {
30	        public float X { get; set; }
31	        public float Y { get; set; }
32	        public float Z { get; set; }
33	        public float Disparity { get; set; }
34	        public float Confidence { get; set; }      // 0.0 – 1.0
35	        public TriangulationTier Tier { get; set; }
36	        public string TierReason { get; set; } = "";
37	    }
38	
39	    public class Triangulator
40	    {
41	        private Mat? _P0, _P1;
42	        private double _baselineM;
43	        private double _fx, _fy, _cx, _cy;
44	
45	        // Tier thresholds (metres)
46	        private const float FullAgreementM    = 0.05f;  // < 5cm  → Tier 1
47	        private const float BlendedAgreementM = 0.15f;  // < 15cm → Tier 2, else bad match
48	
49	        public void Configure(StereoCalibrationData cal)
50	        {
51	            _P0 = ArrayToMat(cal.P0, 3, 4);
52	            _P1 = ArrayToMat(cal.P1, 3, 4);
53	            _fx        =  cal.P0[0];
54	            _fy        =  cal.P0[5];
55	            _cx        =  cal.P0[2];
56	            _cy        =  cal.P0[6];
57	            // Standard OpenCV stereoRectify convention: baseline = -P1[0,3]/P1[0,0].
58	            _baselineM = -cal.P1[3] / cal.P1[0];
59	            Console.WriteLine($"[Triangulator] Baseline: {_baselineM*1000:F1}mm  fx: {_fx:F1}px");
60	        }
61	
62	        // ── Tier 1 / 2: full stereo — both cameras detected the ball ────────────
63	        public TriangulatedPoint TriangulateStereo(PointF pt0, PointF pt1)
64	        {
65	            float disparity = pt0.X - pt1.X;
66	            if (disparity <= 0.5f)
