//
// X is NOT 0 here despite the tee being laterally centered: Triangulator
// reports X relative to camera0's own optical axis, not the stereo pair's
// shared center (see Triangulator.BaselineM's comment) — a truly-centered
// point reports X=+baseline/2. Found live: without this offset, every
// genuinely-at-rest detection looked "displaced" relative to an assumed
// X=0 reference, so the rest-position seed never actually engaged — it
// silently fell back to its degraded (needs 2 real detections) path every
// time, using whatever the first real detection happened to be as a
// fabricated "rest" reference instead.
private void SetTrackerRestPosition() =>
    _tracker.SetRestPosition(_triangulator.BaselineM / 2f, 0f, (float)StereoCalibrationData.DefaultMeasurementDistanceM);

