{
    if (_kf == null) return (mx, my, mz, 0, 0, 0);

    if (!_initialized)
    {
        float dx = mx - RestX, dy = my - RestY, dz = mz - RestZ;
        bool stillAtRest = MathF.Sqrt(dx * dx + dy * dy + dz * dz) <= RestPositionToleranceM;

        if (stillAtRest)
        {
            // Keep refreshing "last seen at rest" so it stays as close as
            // possible to the true moment of impact once the ball moves.
            _lastRestTimestampUs = timestampUs;
            _haveRestTimestamp = true;
            LastState = (RestX, RestY, RestZ, 0, 0, 0);
            return LastState;
        }

        if (_haveRestTimestamp)
        {
            SeedFromRestAndDetection(mx, my, mz, timestampUs);
            return LastState;
        }

        // No rest baseline was ever observed — degrade to the old
        // behavior: treat this detection as the reference and wait for
        // one more real one (see class comment above).
        RestX = mx; RestY = my; RestZ = mz;
        _lastRestTimestampUs = timestampUs;
        _haveRestTimestamp = true;
        LastState = (mx, my, mz, 0, 0, 0);
        return LastState;

