80	        }
81	
82	        [Fact]
83	        public void TriangulateStereo_NegativeDisparity_FallsToMonocular()
84	        {
85	            // pt0.X < pt1.X → disparity ≤ 0 — ball "behind" baseline, physically impossible
86	            var t = MakeTriangulator();
87	            var result = t.TriangulateStereo(new PointF(100f, 512f), new PointF(200f, 512f));
88	
89	            result.Tier.Should().Be(TriangulationTier.Monocular);
90	            result.Confidence.Should().BeLessThan(0.5f);
91	        }
92	
93	        [Fact]
94	        public void TriangulateStereo_ZeroDisparity_FallsToMonocular()
95	        {
96	            // Exactly equal X coordinates → disparity = 0 → undefined depth
97	            var t = MakeTriangulator();
98	            var result = t.TriangulateStereo(new PointF(400f, 400f), new PointF(400f, 400f));
99	
100	            result.Tier.Should().Be(TriangulationTier.Monocular);
101	        }
102	
103	        [Fact]
104	        public void TriangulateStereo_TinyDisparity_ZOutOfRange_FallsToMonocular()
105	        {
106	            // Disparity = 0.2px → Z = 1800*0.70/0.2 = 6300m, far beyond the 10m max.
107	            var t = MakeTriangulator();
108	            var result = t.TriangulateStereo(new PointF(640.2f, 512f), new PointF(640.0f, 512f));
109	
110	            result.Tier.Should().Be(TriangulationTier.Monocular);
111	        }
112	
113	        [Fact]
114	        public void TriangulateStereo_DisparityProportionalToBaseline()
115	        {
116	            // Doubling the baseline should double the recovered Z for the same pixel disparity.
117	            // t70: disparity=630px → Z = 1800*0.70/630 = 2.0m
118	            // t35: same 630px disparity → Z = 1800*0.35/630 = 1.0m
119	            var t70 = MakeTriangulator(baseline: 0.70);
120	            var t35 = MakeTriangulator(baseline: 0.35);
121	
122	            var r70 = t70.TriangulateStereo(new PointF(640f, 512f), new PointF(10f, 512f));
123	            var r35 = t35.TriangulateStereo(new PointF(640f, 512f), new PointF(10f, 512f));
124	
125	            // Both should produce a real stereo result (not Monocular fallback)
126	            r70.Tier.Should().NotBe(TriangulationTier.KalmanOnly);
127	            r35.Tier.Should().NotBe(TriangulationTier.KalmanOnly);
128	
129	            r70.Z.Should().BeApproximately(2.0f, 0.1f);
130	            r35.Z.Should().BeApproximately(1.0f, 0.1f);
131	            r70.Z.Should().BeApproximately(r35.Z * 2f, 0.2f,
132	                "doubling baseline doubles recovered Z for the same pixel disparity");
133	        }
134	
135	        // ── TriangulateMonocular ─────────────────────────────────────────────────
136	
137	        [Fact]
138	        public void TriangulateMonocular_PrincipalPoint_WorldXYIsZero()
139	        {
140	            // A pixel at the principal point back-projects to (0, 0, Z) in world space.
141	            var t = MakeTriangulator();
142	            var result = t.TriangulateMonocular(new PointF(640f, 512f), knownZ: 3.0f);
