1	// ------------------------------------------------------------
2	// Tracking/KalmanBallTracker.cs
3	// ------------------------------------------------------------
4	// Simple 6-state Kalman: [x, y, z, vx, vy, vz]
5	//
6	// Emgu.CV 4.9 matrix-writing notes:
7	//   Marshal.Copy to Mat.DataPointer does NOT reliably update KalmanFilter's
8	//   internal matrices — the native KalmanFilter struct may hold its own
9	//   pointers that differ from the managed Mat wrapper's DataPointer.
10	//
11	//   Reliable approaches:
12	//     • Diagonal matrices  → CvInvoke.SetIdentity(mat, scalar)
13	//     • Arbitrary matrices → build a Matrix<float> (has [r,c] indexer),
14	//                            then call matrix.Mat.CopyTo(target)
15	//     • Reading state      → copy to a Matrix<float> and read [r,c]
16	// ------------------------------------------------------------
17	using System;
18	using Emgu.CV;
19	using Emgu.CV.CvEnum;
20	using Emgu.CV.Structure;
21	using SportSimulator.Models;
22	
23	namespace SportSimulator.Tracking
24	{
25	    public class KalmanBallTracker
26	    {
27	        private KalmanFilter? _kf;
28	        private bool _initialized;
29	        private long _lastTimestampUs;
30	
31	        // Seeding used to buffer several real measurements and least-squares fit a
32	        // line through them (see git history) — needs several independent real
33	        // detections to average noise down. This rig's confirmed camera geometry
34	        // (114in height, ~33in forward, steep downward tilt — see notes/14-...md
35	        // and App/Program.cs) gives a real forward flight-tracking window of only
36	        // ~18 inches at the tee before the ball crosses the bottom of frame —
37	        // confirmed three independent ways this session (tilt-derived geometry,
38	        // a physical tape measurement in SpinView, and the mock's own live
39	        // behavior). At realistic shot speeds that's often only 1-2 real
40	        // detections total, nowhere near enough to average.
41	        //
42	        // Instead: the ball's REST position (address/tee) is a known, calibrated
43	        // point, not something that needs detecting — it's ~zero-noise, unlike a
44	        // second raw camera measurement. Track the last timestamp the ball was
45	        // seen sitting at that known rest position; the instant a real detection
46	        // shows it meaningfully displaced, that's the shot starting, and a single
47	        // two-point delta (known rest position/time -> this one noisy detection)
48	        // gives a velocity estimate with HALF the noise sources of a raw two-point
49	        // delta between two noisy detections, and needs only ONE real detection
50	        // after the ball leaves rest — not several.
51	        //
52	        // If no "at rest" detection ever lands before the first moving one (e.g.
53	        // the ball wasn't visible yet when this shot's tracking began), falls back
54	        // to treating that first detection itself as the rest reference and
55	        // waiting for one more real detection — worse (back to needing 2 real
56	        // detections instead of 1) but never wrong, and it's the same degraded
57	        // behavior this tracker already had before this change. A real hardware
58	        // impact trigger (IR break-beam/mic — see notes/04-hardware-triggering.md)
59	        // would slot in as a strictly more precise t0 if/when this rig has one, by
60	        // calling SetRestPosition/feeding that trigger's timestamp in instead of
61	        // relying on a camera-inferred one — nothing else here would need to change.
62	        private const float RestPositionToleranceM = 0.03f; // ball radius is a few cm; this must be well under one ball-width of drift
63	        public float RestX { get; private set; }
64	        public float RestY { get; private set; }
65	        public float RestZ { get; private set; }
66	        private long _lastRestTimestampUs;
67	        private bool _haveRestTimestamp;
68	
69	        // Fallback dt for the very first Update/Predict call, when there's no prior
70	        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
71	        // reports 199.76fps at default (full-frame) settings.
72	        private const float DefaultDt = 1f / 199.76f;
73	
74	        // Guards against a degenerate transition matrix: MinDt covers duplicate/
75	        // non-monotonic timestamps (would otherwise give dt<=0), MaxDt caps a single
76	        // huge gap (e.g. a long coast) from producing an absurd position jump — real
77	        // coast-frame limits (SportProfile.KalmanCoastFrames) bound this in practice.
78	        private const float MinDt = 1e-4f;
79	        private const float MaxDt = 0.5f;
80	
81	        public void Configure(SportProfile profile)
82	        {
83	            _kf = new KalmanFilter(6, 3, 0, DepthType.Cv32F);
84	            float q = profile.ProcessNoise;
85	            float r = profile.MeasurementNoise;
86	
87	            SetTransitionMatrix(DefaultDt);
88	
89	            SetMatrix(_kf.MeasurementMatrix, new float[,]
90	            {
91	                {1,0,0,0,0,0},
92	                {0,1,0,0,0,0},
93	                {0,0,1,0,0,0}
94	            });
95	
96	            // CvInvoke.SetIdentity is the reliable way to set diagonal Mats
97	            CvInvoke.SetIdentity(_kf.ProcessNoiseCov,     new MCvScalar(q));
98	            CvInvoke.SetIdentity(_kf.MeasurementNoiseCov, new MCvScalar(r));
99	            CvInvoke.SetIdentity(_kf.ErrorCovPost,        new MCvScalar(1.0));
100	
101	            _initialized = false;
102	            _haveRestTimestamp = false;
103	        }
104	
105	        // The ball's known calibrated address/tee position, in the same (camera-
106	        // local) coordinate frame Triangulator reports — for this rig that's
107	        // (0, 0, StereoCalibrationData.DefaultMeasurementDistanceM) since the tee
108	        // sits dead center on the stereo pair's shared boresight (confirmed
109	        // on-site: "vertically centered in the fov", no lateral offset). Call once
110	        // after Configure(), before the first Update() of a new shot.
111	        public void SetRestPosition(float x, float y, float z)
112	        {
113	            RestX = x; RestY = y; RestZ = z;
114	            _haveRestTimestamp = false;
115	        }
116	
117	        // Position-only measurement update. timestampUs is the frame's own capture
118	        // timestamp — NOT wall-clock time of when this method happens to be called.
119	        // The transition matrix's dt is rebuilt from the real elapsed time since the
120	        // last call rather than assumed fixed, because callers don't call this once
121	        // per camera tick: SimulatorEngine.ProcessLoop batches a variable number of
122	        // frames per cycle depending on processing load, so a hardcoded dt here
123	        // systematically distorted the recovered velocity — see App/SimulatorEngine.cs
124	        // ProcessLoop and this class's git history for the incident that caught it
125	        // (mock ball moved far too slowly because reported speed was ~10x too low).
126	        public (float x, float y, float z, float vx, float vy, float vz) Update(
127	            float mx, float my, float mz, long timestampUs)
128	        {
129	            if (_kf == null) return (mx, my, mz, 0, 0, 0);
130	
131	            if (!_initialized)
132	            {
133	                float dx = mx - RestX, dy = my - RestY, dz = mz - RestZ;
134	                bool stillAtRest = MathF.Sqrt(dx * dx + dy * dy + dz * dz) <= RestPositionToleranceM;
135	
136	                if (stillAtRest)
137	                {
138	                    // Keep refreshing "last seen at rest" so it stays as close as
139	                    // possible to the true moment of impact once the ball moves.
140	                    _lastRestTimestampUs = timestampUs;
141	                    _haveRestTimestamp = true;
142	                    LastState = (RestX, RestY, RestZ, 0, 0, 0);
143	                    return LastState;
144	                }
145	
146	                if (_haveRestTimestamp)
147	                {
148	                    SeedFromRestAndDetection(mx, my, mz, timestampUs);
149	                    return LastState;
150	                }
151	
152	                // No rest baseline was ever observed — degrade to the old
153	                // behavior: treat this detection as the reference and wait for
154	                // one more real one (see class comment above).
155	                RestX = mx; RestY = my; RestZ = mz;
156	                _lastRestTimestampUs = timestampUs;
157	                _haveRestTimestamp = true;
158	                LastState = (mx, my, mz, 0, 0, 0);
159	                return LastState;
160	            }
161	
162	            SetTransitionMatrix(RealDt(timestampUs));
163	            _kf.Predict();
164	
165	            using var meas = new Matrix<float>(3, 1);
166	            meas[0, 0] = mx; meas[1, 0] = my; meas[2, 0] = mz;
167	
168	            CacheState(_kf.Correct(meas.Mat));
169	            _lastTimestampUs = timestampUs;
170	            return LastState;
171	        }
172	
173	        /// <summary>Predict-only step (Tier 4 coasting). See Update's comment on timestampUs.</summary>
174	        public (float x, float y, float z, float vx, float vy, float vz) Predict(long timestampUs)
175	        {
176	            if (_kf == null || !_initialized) return LastState;
177	            SetTransitionMatrix(RealDt(timestampUs));
178	            CacheState(_kf.Predict());
179	            _lastTimestampUs = timestampUs;
180	            return LastState;
181	        }
182	
183	        // Seeds directly from a single two-point delta: the known (zero-noise)
184	        // rest position/timestamp, to this one real (noisy) detection. Position
185	        // is trusted at face value (it's the only real measurement available);
186	        // velocity is the delta divided by real elapsed time since the ball was
187	        // last seen at rest. Commits with no extra Predict() step, since this
188	        // detection's timestamp IS "now" — advancing again would overshoot.
189	        private void SeedFromRestAndDetection(float mx, float my, float mz, long timestampUs)
190	        {
191	            float dt = ClampDt((timestampUs - _lastRestTimestampUs) / 1_000_000f);
192	            float vx = (mx - RestX) / dt;
193	            float vy = (my - RestY) / dt;
194	            float vz = (mz - RestZ) / dt;
195	
196	            using var init = new Matrix<float>(6, 1);
197	            init[0, 0] = mx; init[1, 0] = my; init[2, 0] = mz;
198	            init[3, 0] = vx; init[4, 0] = vy; init[5, 0] = vz;
199	            init.Mat.CopyTo(_kf!.StatePost);
200	
201	            SetTransitionMatrix(dt);
202	            _initialized = true;
203	            CacheState(_kf.StatePost);
204	            _lastTimestampUs = timestampUs;
205	        }
206	
207	        private float RealDt(long timestampUs) => ClampDt((timestampUs - _lastTimestampUs) / 1_000_000f);
208	
209	        private static float ClampDt(float dt) => Math.Max(MinDt, Math.Min(MaxDt, dt));
210	
211	        private void SetTransitionMatrix(float dt)
212	        {
213	            SetMatrix(_kf!.TransitionMatrix, new float[,]
214	            {
215	                {1,0,0,dt,0,0},
216	                {0,1,0,0,dt,0},
217	                {0,0,1,0,0,dt},
218	                {0,0,0,1,0,0},
219	                {0,0,0,0,1,0},
220	                {0,0,0,0,0,1}
221	            });
222	        }
223	
224	        public (float x, float y, float z, float vx, float vy, float vz) LastState
225	        { get; private set; }
226	
227	        // True once the rest-position velocity seed has committed (see
228	        // SeedFromRestAndDetection). Callers feeding this tracker single-camera
229	        // monocular estimates that fall back to LastState.z as their own depth
230	        // reference (SimulatorEngine's Tier 3) should check this first — before
231	        // it's true, LastState.z is meaningless (0), and treating it as a real
232	        // depth would feed a fabricated point into the seed.
233	        public bool HasFix => _initialized;
234	
235	        // ── Helpers ──────────────────────────────────────────────────────────
236	
237	        private void CacheState(Mat state)
238	        {
239	            // state is a 6x1 CV_32F Mat returned by Predict/Correct
240	            using var m = new Matrix<float>(state.Rows, 1);
241	            state.CopyTo(m.Mat);
242	            LastState = (m[0,0], m[1,0], m[2,0], m[3,0], m[4,0], m[5,0]);
243	        }
244	
245	        // Build a Matrix<float> from a 2-D array and copy it into a target Mat.
246	        private static void SetMatrix(Mat target, float[,] vals)
247	        {
248	            int rows = vals.GetLength(0), cols = vals.GetLength(1);
249	            using var m = new Matrix<float>(rows, cols);
250	            for (int r = 0; r < rows; r++)
251	                for (int c = 0; c < cols; c++)
252	                    m[r, c] = vals[r, c];
253	            m.Mat.CopyTo(target);
254	        }
255	    }
256	}
