// Seeds directly from a single two-point delta: the known (zero-noise)
// rest position/timestamp, to this one real (noisy) detection. Position
// is trusted at face value (it's the only real measurement available);
// velocity is the delta divided by real elapsed time since the ball was
// last seen at rest. Commits with no extra Predict() step, since this
// detection's timestamp IS "now" — advancing again would overshoot.
private void SeedFromRestAndDetection(float mx, float my, float mz, long timestampUs)
{
    float dt = ClampDt((timestampUs - _lastRestTimestampUs) / 1_000_000f);
    float vx = (mx - RestX) / dt;
    float vy = (my - RestY) / dt;
    float vz = (mz - RestZ) / dt;

    using var init = new Matrix<float>(6, 1);
    init[0, 0] = mx; init[1, 0] = my; init[2, 0] = mz;
    init[3, 0] = vx; init[4, 0] = vy; init[5, 0] = vz;
    init.Mat.CopyTo(_kf!.StatePost);

    SetTransitionMatrix(dt);
    _initialized = true;
    CacheState(_kf.StatePost);

