1	// ------------------------------------------------------------
2	// Tracking/KalmanBallTracker.cs
3	// ------------------------------------------------------------
4	// Simple 6-state Kalman: [x, y, z, vx, vy, vz]
5	//
6	// Emgu.CV 4.9 matrix-writing notes:
7	//   Marshal.Copy to Mat.DataPointer does NOT reliably update KalmanFilter's
8	//   internal matrices — the native KalmanFilter struct may hold its own
9	//   pointers that differ from the managed Mat wrapper's DataPointer.
10	//
11	//   Reliable approaches:
12	//     • Diagonal matrices  → CvInvoke.SetIdentity(mat, scalar)
13	//     • Arbitrary matrices → build a Matrix<float> (has [r,c] indexer),
14	//                            then call matrix.Mat.CopyTo(target)
15	//     • Reading state      → copy to a Matrix<float> and read [r,c]
16	// ------------------------------------------------------------
17	using System;
18	using Emgu.CV;
19	using Emgu.CV.CvEnum;
20	using Emgu.CV.Structure;
21	using SportSimulator.Models;
22	
23	namespace SportSimulator.Tracking
24	{
25	    public class KalmanBallTracker
26	    {
27	        private KalmanFilter? _kf;
28	        private bool _initialized;
29	        private long _lastTimestampUs;
30	
31	        // Seeding used to buffer several real measurements and least-squares fit a
32	        // line through them (see git history) — needs several independent real
33	        // detections to average noise down. This rig's confirmed camera geometry
34	        // (114in height, ~33in forward, steep downward tilt — see notes/14-...md
35	        // and App/Program.cs) gives a real forward flight-tracking window of only
36	        // ~18 inches at the tee before the ball crosses the bottom of frame —
37	        // confirmed three independent ways this session (tilt-derived geometry,
38	        // a physical tape measurement in SpinView, and the mock's own live
39	        // behavior). At realistic shot speeds that's often only 1-2 real
40	        // detections total, nowhere near enough to average.
41	        //
42	        // Instead: the ball's REST position (address) is measured live — a
43	        // running average of real detections that agree with each other (i.e. the
44	        // ball is confirmed sitting still) — rather than assumed from a fixed
45	        // calibration constant. This handles a ball placed anywhere within frame,
46	        // not just an exact marked spot (a fixed-position version of this existed
47	        // briefly first, but broke the moment the ball wasn't placed exactly on
48	        // the calibrated tee — see conversation). There's no time pressure before
49	        // the shot the way there is during the ~1-2-frame flight window, so this
50	        // average can refine for as long as the ball actually sits still, getting
51	        // MORE accurate the longer it waits — genuinely more precise than a fixed
52	        // assumption, not just a fallback for one.
53	        //
54	        // The instant a real detection shows up meaningfully displaced from that
55	        // average, that's the shot starting: a single two-point delta (averaged
56	        // rest position/time -> this one noisy detection) gives a velocity
57	        // estimate with far less noise than a raw two-point delta between two
58	        // arbitrary noisy detections, and needs only ONE real detection after the
59	        // ball leaves rest — not several.
60	        //
61	        // Can't fully distinguish "the ball just became visible, already moving"
62	        // from "the ball was genuinely at rest and just moved" from a single
63	        // sample — both start the same way (first-ever detection, nothing to
64	        // compare against yet). Requiring several consecutive agreeing samples
65	        // before trusting the average (MinRestSamplesForConfidence) reduces, but
66	        // can't eliminate, that ambiguity; with fewer samples the velocity
67	        // estimate still computes, just noisier. A real hardware impact trigger
68	        // (IR break-beam/mic — see notes/04-hardware-triggering.md) would remove
69	        // this ambiguity entirely if this rig ever has one, by supplying a known
70	        // t0 independent of any position heuristic — nothing else here would need
71	        // to change to use it.
72	        private const float RestPositionToleranceM = 0.03f; // ball radius is a few cm; this must be well under one ball-width of drift
73	        private const int MinRestSamplesForConfidence = 5; // consecutive agreeing samples before the average is trusted, not just accepted
74	        private float _restSumX, _restSumY, _restSumZ;
75	        private int _restSampleCount;
76	        private long _lastRestTimestampUs;
77	
78	        public float RestX => _restSampleCount > 0 ? _restSumX / _restSampleCount : 0f;
79	        public float RestY => _restSampleCount > 0 ? _restSumY / _restSampleCount : 0f;
80	        public float RestZ => _restSampleCount > 0 ? _restSumZ / _restSampleCount : 0f;
81	        public int RestSampleCount => _restSampleCount;
82	
83	        // Fallback dt for the very first Update/Predict call, when there's no prior
84	        // timestamp to diff against yet. Confirmed on-site 2026-07-22: SpinView
85	        // reports 199.76fps at default (full-frame) settings.
86	        private const float DefaultDt = 1f / 199.76f;
87	
88	        // Guards against a degenerate transition matrix: MinDt covers duplicate/
89	        // non-monotonic timestamps (would otherwise give dt<=0), MaxDt caps a single
90	        // huge gap (e.g. a long coast) from producing an absurd position jump — real
91	        // coast-frame limits (SportProfile.KalmanCoastFrames) bound this in practice.
92	        private const float MinDt = 1e-4f;
93	        private const float MaxDt = 0.5f;
94	
95	        public void Configure(SportProfile profile)
96	        {
97	            _kf = new KalmanFilter(6, 3, 0, DepthType.Cv32F);
98	            float q = profile.ProcessNoise;
99	            float r = profile.MeasurementNoise;
100	
101	            SetTransitionMatrix(DefaultDt);
102	
103	            SetMatrix(_kf.MeasurementMatrix, new float[,]
104	            {
105	                {1,0,0,0,0,0},
106	                {0,1,0,0,0,0},
107	                {0,0,1,0,0,0}
108	            });
109	
110	            // CvInvoke.SetIdentity is the reliable way to set diagonal Mats
111	            CvInvoke.SetIdentity(_kf.ProcessNoiseCov,     new MCvScalar(q));
112	            CvInvoke.SetIdentity(_kf.MeasurementNoiseCov, new MCvScalar(r));
113	            CvInvoke.SetIdentity(_kf.ErrorCovPost,        new MCvScalar(1.0));
114	
115	            _initialized = false;
116	            _restSumX = _restSumY = _restSumZ = 0f;
117	            _restSampleCount = 0;
118	        }
119	
120	        // Position-only measurement update. timestampUs is the frame's own capture
121	        // timestamp — NOT wall-clock time of when this method happens to be called.
122	        // The transition matrix's dt is rebuilt from the real elapsed time since the
123	        // last call rather than assumed fixed, because callers don't call this once
124	        // per camera tick: SimulatorEngine.ProcessLoop batches a variable number of
125	        // frames per cycle depending on processing load, so a hardcoded dt here
126	        // systematically distorted the recovered velocity — see App/SimulatorEngine.cs
127	        // ProcessLoop and this class's git history for the incident that caught it
128	        // (mock ball moved far too slowly because reported speed was ~10x too low).
129	        public (float x, float y, float z, float vx, float vy, float vz) Update(
130	            float mx, float my, float mz, long timestampUs)
131	        {
132	            if (_kf == null) return (mx, my, mz, 0, 0, 0);
133	
134	            if (!_initialized)
135	            {
136	                if (_restSampleCount == 0)
137	                {
138	                    // First-ever detection: nothing to compare against yet. Seed
139	                    // the running average with it and wait for the next one to
140	                    // tell us whether the ball is sitting still or already moving.
141	                    _restSumX = mx; _restSumY = my; _restSumZ = mz;
142	                    _restSampleCount = 1;
143	                    _lastRestTimestampUs = timestampUs;
144	                    LastState = (mx, my, mz, 0, 0, 0);
145	                    return LastState;
146	                }
147	
148	                float avgX = RestX, avgY = RestY, avgZ = RestZ;
149	                float dx = mx - avgX, dy = my - avgY, dz = mz - avgZ;
150	                bool stillAtRest = MathF.Sqrt(dx * dx + dy * dy + dz * dz) <= RestPositionToleranceM;
151	
152	                if (stillAtRest)
153	                {
154	                    // Fold this sample into the running average — more samples
155	                    // while genuinely at rest means a lower-noise reference, not
156	                    // just a fallback: there's no time pressure before the shot
157	                    // the way there is during the ~1-2-frame flight window.
158	                    _restSumX += mx; _restSumY += my; _restSumZ += mz;
159	                    _restSampleCount++;
160	                    _lastRestTimestampUs = timestampUs;
161	                    LastState = (RestX, RestY, RestZ, 0, 0, 0);
162	                    return LastState;
163	                }
164	
165	                // Displaced from the rest average — the shot just started. Seed
166	                // directly from a two-point delta (see class comment): works the
167	                // same whether the average is built from hundreds of samples or
168	                // just one — noisier in the latter case, but never wrong.
169	                SeedFromRestAndDetection(mx, my, mz, timestampUs, avgX, avgY, avgZ);
170	                return LastState;
171	            }
172	
173	            SetTransitionMatrix(RealDt(timestampUs));
174	            _kf.Predict();
175	
176	            using var meas = new Matrix<float>(3, 1);
177	            meas[0, 0] = mx; meas[1, 0] = my; meas[2, 0] = mz;
178	
179	            CacheState(_kf.Correct(meas.Mat));
180	            _lastTimestampUs = timestampUs;
181	            return LastState;
182	        }
183	
184	        /// <summary>Predict-only step (Tier 4 coasting). See Update's comment on timestampUs.</summary>
185	        public (float x, float y, float z, float vx, float vy, float vz) Predict(long timestampUs)
186	        {
187	            if (_kf == null || !_initialized) return LastState;
188	            SetTransitionMatrix(RealDt(timestampUs));
189	            CacheState(_kf.Predict());
190	            _lastTimestampUs = timestampUs;
191	            return LastState;
192	        }
193	
194	        // Seeds directly from a single two-point delta: the measured (averaged,
195	        // low-noise once several samples have accumulated) rest position/timestamp,
196	        // to this one real (noisy) detection. Position is trusted at face value
197	        // (it's the only real measurement available); velocity is the delta
198	        // divided by real elapsed time since the ball was last seen at rest.
199	        // Commits with no extra Predict() step, since this detection's timestamp
200	        // IS "now" — advancing again would overshoot.
201	        private void SeedFromRestAndDetection(float mx, float my, float mz, long timestampUs,
202	                                               float restX, float restY, float restZ)
203	        {
204	            float dt = ClampDt((timestampUs - _lastRestTimestampUs) / 1_000_000f);
205	            float vx = (mx - restX) / dt;
206	            float vy = (my - restY) / dt;
207	            float vz = (mz - restZ) / dt;
208	
209	            using var init = new Matrix<float>(6, 1);
210	            init[0, 0] = mx; init[1, 0] = my; init[2, 0] = mz;
211	            init[3, 0] = vx; init[4, 0] = vy; init[5, 0] = vz;
212	            init.Mat.CopyTo(_kf!.StatePost);
213	
214	            SetTransitionMatrix(dt);
215	            _initialized = true;
216	            CacheState(_kf.StatePost);
217	            _lastTimestampUs = timestampUs;
218	        }
219	
220	        private float RealDt(long timestampUs) => ClampDt((timestampUs - _lastTimestampUs) / 1_000_000f);
221	
222	        private static float ClampDt(float dt) => Math.Max(MinDt, Math.Min(MaxDt, dt));
223	
224	        private void SetTransitionMatrix(float dt)
225	        {
226	            SetMatrix(_kf!.TransitionMatrix, new float[,]
227	            {
228	                {1,0,0,dt,0,0},
229	                {0,1,0,0,dt,0},
230	                {0,0,1,0,0,dt},
231	                {0,0,0,1,0,0},
232	                {0,0,0,0,1,0},
233	                {0,0,0,0,0,1}
234	            });
235	        }
236	
237	        public (float x, float y, float z, float vx, float vy, float vz) LastState
238	        { get; private set; }
239	
240	        // True once the rest-position velocity seed has committed (see
241	        // SeedFromRestAndDetection). Callers feeding this tracker single-camera
242	        // monocular estimates that fall back to LastState.z as their own depth
243	        // reference (SimulatorEngine's Tier 3) should check this first — before
244	        // it's true, LastState.z is meaningless (0), and treating it as a real
245	        // depth would feed a fabricated point into the seed.
246	        public bool HasFix => _initialized;
247	
248	        // ── Helpers ──────────────────────────────────────────────────────────
249	
250	        private void CacheState(Mat state)
251	        {
252	            // state is a 6x1 CV_32F Mat returned by Predict/Correct
253	            using var m = new Matrix<float>(state.Rows, 1);
254	            state.CopyTo(m.Mat);
255	            LastState = (m[0,0], m[1,0], m[2,0], m[3,0], m[4,0], m[5,0]);
256	        }
257	
258	        // Build a Matrix<float> from a 2-D array and copy it into a target Mat.
259	        private static void SetMatrix(Mat target, float[,] vals)
260	        {
261	            int rows = vals.GetLength(0), cols = vals.GetLength(1);
262	            using var m = new Matrix<float>(rows, cols);
263	            for (int r = 0; r < rows; r++)
264	                for (int c = 0; c < cols; c++)
265	                    m[r, c] = vals[r, c];
266	            m.Mat.CopyTo(target);
267	        }
268	    }
