4	using FluentAssertions;
5	using SportSimulator.Models;
6	using SportSimulator.Tracking;
7	using Xunit;
8	
9	namespace SportSimulator.Tests
10	{
11	    public class KalmanTrackerTests
12	    {
13	        private static KalmanBallTracker MakeTracker(float processNoise = 0.01f,
14	                                                      float measureNoise  = 0.1f)
15	        {
16	            var tracker = new KalmanBallTracker();
17	            tracker.Configure(new SportProfile
18	            {
19	                SportId          = "test",
20	                ProcessNoise     = processNoise,
21	                MeasurementNoise = measureNoise,
22	                KalmanCoastFrames = 5
23	            });
24	            return tracker;
25	        }
26	
27	        [Fact]
28	        public void FirstUpdate_ReturnsInputPosition()
29	        {
30	            var tracker = MakeTracker();
31	            var (x, y, z, _, _, _) = tracker.Update(1f, 2f, 3f, 0);
32	
33	            // First update seeds the filter — position should be very close to input
34	            x.Should().BeApproximately(1f, 0.5f);
35	            y.Should().BeApproximately(2f, 0.5f);
36	            z.Should().BeApproximately(3f, 0.5f);
37	        }
38	
39	        [Fact]
40	        public void ConstantVelocityTrajectory_PositionTracksAndVelocityConvergesEarly()
41	        {
42	            // KalmanBallTracker seeds its initial velocity from a rest-position delta
43	            // (see its class comment) rather than starting at zero — a real capture
44	            // window doesn't give a fast-moving ball hundreds of frames to "learn" its
45	            // own speed from scratch. So for a truly constant-velocity trajectory,
46	            // velocity should already be close to true almost immediately, and stay
47	            // close — not slowly climb over time.
48	            var tracker = MakeTracker();
49	            float dt = 1f / 120f;
50	            float vxTrue = 10f;
51	
52	            // Ball sits at rest before the shot — every real shot starts this way
53	            // (see KalmanBallTracker.Update's settling gate, MinRestSamplesForConfidence)
54	            // — feed enough agreeing samples to clear it before any real motion.
55	            const int restSamples = 5;
56	            for (int i = 0; i < restSamples; i++)
57	                tracker.Update(0f, 0f, 5f, (long)((i - restSamples) * dt * 1_000_000f));
58	
59	            for (int i = 0; i < 10; i++)
60	                tracker.Update(i * dt * vxTrue, 0f, 5f, (long)(i * dt * 1_000_000f));
61	            var (_, _, _, vxEarly, _, _) = tracker.LastState;
62	
63	            for (int i = 10; i < 60; i++)
64	                tracker.Update(i * dt * vxTrue, 0f, 5f, (long)(i * dt * 1_000_000f));
65	
66	            var (px, _, _, vxLate, _, _) = tracker.LastState;
67	            float expectedX = 59 * dt * vxTrue;
68	
69	            px.Should().BeApproximately(expectedX, 0.25f,
70	                "position estimate should be within 25cm of measured position");
71	            vxEarly.Should().BeApproximately(vxTrue, 0.1f,
72	                "rest-position seeding should recover the true velocity almost immediately, not after many frames");
73	            vxLate.Should().BeApproximately(vxTrue, 0.1f,
74	                "velocity estimate should stay close to true — a perfectly constant-velocity trajectory has nothing left to converge on");
75	        }
76	
77	        [Fact]
78	        public void Predict_WithoutMeasurement_AdvancesPosition()
79	        {
80	            var tracker = MakeTracker();
81	            // Ball sits at rest before the shot (see MinRestSamplesForConfidence's
82	            // settling gate in KalmanBallTracker.Update), then moves at a steady
83	            // ~10 m/s along x, ~48 m/s along z so the seed lands on a real, moving
84	            // state once it's displaced from rest.
85	            const long dtUs = 5006;
86	            const int restSamples = 5;
87	            for (int i = 0; i < restSamples; i++)
88	                tracker.Update(0f, 0f, 5f, (i - restSamples) * dtUs);
89	            for (int i = 0; i < 8; i++)
90	                tracker.Update(i * 0.05006f, 0f, 5f + i * 0.24f, i * dtUs);
91	
92	            var (x0, _, _, _, _, _) = tracker.LastState;
93	            tracker.Predict(8 * dtUs + dtUs);
94	            var (x1, _, _, _, _, _) = tracker.LastState;
95	
96	            x1.Should().BeGreaterThan(x0, "predict-only step should advance position");
97	        }
98	
99	        [Fact]
100	        public void MultiplePredicts_DoNotExplode()
101	        {
102	            // Coasting should never produce NaN or very large values
103	            var tracker = MakeTracker();
104	            const long dtUs = 5006;
105	            const int restSamples = 5;
106	            for (int i = 0; i < restSamples; i++)
107	                tracker.Update(0f, 0f, 5f, (i - restSamples) * dtUs);
108	            for (int i = 0; i < 8; i++)
109	                tracker.Update(i * 0.05006f, 0f, 5f + i * 0.24f, i * dtUs);
110	
111	            for (int i = 0; i < 10; i++) tracker.Predict(8 * dtUs + (i + 1) * dtUs);
112	
113	            var (x, y, z, vx, vy, vz) = tracker.LastState;
114	            float[] vals = { x, y, z, vx, vy, vz };
115	            foreach (var v in vals)
116	            {
117	                float.IsNaN(v).Should().BeFalse("coasting should not produce NaN");
118	                System.Math.Abs(v).Should().BeLessThan(1000f, "coasting should not explode");
119	            }
120	        }
121	
122	        [Fact]
123	        public void Configure_ResetsFilter()
124	        {
125	            // After reconfigure the filter should accept a new trajectory cleanly
126	            var tracker = MakeTracker();
127	            tracker.Update(100f, 50f, 200f, 0);
128	            tracker.Update(101f, 50f, 205f, 5006);
129	
130	            // Reconfigure for a different sport
131	            tracker.Configure(new SportProfile
132	            {
133	                SportId = "golf", ProcessNoise = 0.005f, MeasurementNoise = 0.07f
134	            });
135	            var (x, y, z, _, _, _) = tracker.Update(0f, 0f, 1f, 0);
136	
137	            x.Should().BeApproximately(0f, 0.5f, "filter should be reset after Configure");
138	        }
139	    }
140	}
